-- AiKYNETIX — Аналіз техніки та біомеханіка
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'aikynetix.com' OR LOWER(`name`) = LOWER('AiKYNETIX'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'AiKYNETIX', NULL, 'https://aikynetix.com', NULL, NULL, 'AiKYNETIX — AI-аналітика руху, що перетворює будь-яку камеру на біомеханічну лабораторію: скелет, кути суглобів і валідована біомеханіка з одного відео з телефона для бігу, реабілітації, силових вправ і ергономіки.', 'AiKYNETIX is AI motion analytics that turns any camera into a biomechanics lab: skeleton overlay, joint angles and validated biomechanics from a single phone video for running, rehab, lifting and ergonomics.', 'AiKYNETIX виріс із проблеми бігуна та переконання, що біомеханіка лабораторного рівня не повинна залишатися лише в лабораторії. Сервіс аналізує одне відео з телефона й накладає скелет, вимірює кути суглобів і видає валідовані біомеханічні показники — без сенсорів і спеціального обладнання. Рішення охоплює три напрями: спортивну продуктивність, де тренери можуть проводити скринінг складу й відстежувати прогрес атлетів, охорону здоров''я з об''єктивними даними про ходу й функціональний стан, а також добробут на робочому місці з оцінкою постави й ергономічних ризиків. Почати можна безплатно, є демонстрація, тарифи й блог.', 'AiKYNETIX grew out of a runner''s problem and the conviction that lab-grade biomechanics shouldn''t stay locked in the lab. It analyzes a single phone clip to overlay a skeleton, measure joint angles and produce validated biomechanics — no sensors and no lab. It covers three areas: sports performance, where coaches can screen the roster and progress athletes; healthcare, with objective gait and functional data; and workplace wellness, with posture and ergonomic risk screening. You can start for free, and there are demos, pricing and a blog.', 'Аналіз руху з одного відео
Скелет і кути суглобів
Валідована біомеханіка
Біг, реабілітація, силові
Оцінка постави й ергономіки
Безплатний старт', 'Motion analysis from one video
Skeleton and joint angles
Validated biomechanics
Running, rehab, lifting
Posture and ergonomics screening
Free to start', 'Тренери, клініцисти, бігуни й фахівці з охорони праці.', 'Coaches, clinicians, runners and occupational health specialists.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
SET @pid = (SELECT `id` FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'aikynetix.com' OR LOWER(`name`) = LOWER('AiKYNETIX')) ORDER BY `id` LIMIT 1);
INSERT IGNORE INTO `product_categories` (`product_id`, `category_id`) SELECT @pid, c.`id` FROM `categories` c WHERE @pid IS NOT NULL AND c.`slug` = 'sports' LIMIT 1;
INSERT IGNORE INTO `product_subcategories` (`product_id`, `subcategory_id`) SELECT @pid, s.`id` FROM `subcategories` s JOIN `categories` c ON c.`id` = s.`category_id` WHERE @pid IS NOT NULL AND c.`slug` = 'sports' AND s.`name` = 'Аналіз техніки та біомеханіка' LIMIT 1;
INSERT IGNORE INTO `product_subcategories` (`product_id`, `subcategory_id`) SELECT @pid, s.`id` FROM `subcategories` s JOIN `categories` c ON c.`id` = s.`category_id` WHERE @pid IS NOT NULL AND c.`slug` = 'sports' AND s.`name` = 'Моніторинг навантаження та відновлення' LIMIT 1;
INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'short_description', 'en', 'AiKYNETIX is AI motion analytics that turns any camera into a biomechanics lab: skeleton overlay, joint angles and validated biomechanics from a single phone video for running, rehab, lifting and ergonomics.', 'manual' FROM DUAL WHERE @new = 1;
INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'AiKYNETIX grew out of a runner''s problem and the conviction that lab-grade biomechanics shouldn''t stay locked in the lab. It analyzes a single phone clip to overlay a skeleton, measure joint angles and produce validated biomechanics — no sensors and no lab. It covers three areas: sports performance, where coaches can screen the roster and progress athletes; healthcare, with objective gait and functional data; and workplace wellness, with posture and ergonomic risk screening. You can start for free, and there are demos, pricing and a blog.', 'manual' FROM DUAL WHERE @new = 1;
