-- Best Bike Split — Аналіз техніки та біомеханіка
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'bestbikesplit.com' OR LOWER(`name`) = LOWER('Best Bike Split'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Best Bike Split', NULL, 'https://www.bestbikesplit.com', NULL, NULL, 'Best Bike Split — фізично обґрунтовані плани розподілу потужності для велогонок і тріатлону: моделювання на реальних даних траси, погоди та вашого профілю потужності показує, як швидко ви можете проїхати й як цього досягти.', 'Best Bike Split offers physics-based power pacing plans for cycling and triathlon: modeling with real course data, weather and your power profile shows how fast you can ride and how to achieve it.', 'Best Bike Split допомагає проїхати велоетап якомога швидше. Сервіс використовує фізичне моделювання, реальні дані траси, прогноз погоди та ваш персональний профіль потужності, щоб показати, який час ви можете показати, і скласти оптимальний план розподілу потужності на гонку. Його використовують як аматори, так і професійні команди WorldTour. Преміум-функції допомагають планувати й тренуватися під конкретні старти, виконувати оптимальний план у день гонки та отримувати знання для досягнення сезонних цілей. Почати можна з безплатного базового акаунта, а потім перейти на щомісячну чи вигіднішу річну підписку атлета; є окремі тарифи для тренерів і прев''ю подій.', 'Best Bike Split helps you ride your fastest bike split. It uses physics-based modeling, real course data, weather forecasts and your personal power profile to show what time you can achieve and to build an optimal race pacing plan. Both amateurs and pro WorldTour teams use it. Premium features help you plan and train for specific races, execute your optimal race-day pacing plan and gain knowledge to reach season goals. You can start with a free basic account, then move to a monthly or better-value annual athlete subscription; there are separate coach plans and event previews.', 'Фізичне моделювання часу на етапі
Реальні дані траси й погоди
Персональний профіль потужності
План розподілу потужності
Тарифи для атлетів і тренерів
Безплатний базовий акаунт', 'Physics-based split modeling
Real course and weather data
Personal power profile
Power pacing plan
Plans for athletes and coaches
Free basic account', 'Велогонщики, тріатлоністи та їхні тренери.', 'Bike racers, triathletes and their coaches.', 'web', 'basic', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
