INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Best Bike Split helps you ride your fastest bike split. It uses physics-based modeling, real course data, weather forecasts and your personal power profile to show what time you can achieve and to build an optimal race pacing plan. Both amateurs and pro WorldTour teams use it. Premium features help you plan and train for specific races, execute your optimal race-day pacing plan and gain knowledge to reach season goals. You can start with a free basic account, then move to a monthly or better-value annual athlete subscription; there are separate coach plans and event previews.', 'manual' FROM DUAL WHERE @new = 1;
