SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'captury.com' OR LOWER(`name`) = LOWER('Captury'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Captury', NULL, 'https://captury.com', NULL, NULL, 'Captury — технологія безмаркерного захоплення руху в реальному часі та постобробці: повне тіло, пальці й міміка кількох людей одночасно; рішення DARI для спортивної продуктивності, велнесу та медицини.', 'Captury offers markerless motion capture in real time and post-processing: full body, fingers and facial expressions for multiple people at once; DARI solutions for sports performance, wellness and healthcare.', 'Captury пропонує передові безмаркерні рішення для захоплення руху, які точно відстежують рух усього тіла, пальців і міміку кількох людей одночасно — без костюмів і маркерів. Це підвищує ефективність захоплення руху та зменшує витрати часу й коштів. Обробка можлива в реальному часі або постфактум. Технологію застосовують у розробці 3D-ігор, VFX, кіно й рекламі, віртуальній реальності та інших сферах. Для спорту та здоров''я компанія розвиває продукти DARI Performance, DARI Wellness і DARI Healthcare — системи оцінки руху для спортсменів, оздоровчих програм і медицини. Доступні інтеграції з іншими інструментами.', 'Captury offers advanced markerless motion capture solutions that precisely track full-body motion, finger movements and facial expressions for multiple actors at once — without suits or markers. This makes motion capture more efficient and reduces time and cost. Processing can happen in real time or afterwards. The technology is used in 3D game development, VFX, film and advertising, virtual reality and more. For sports and health the company develops DARI Performance, DARI Wellness and DARI Healthcare — movement assessment systems for athletes, wellness programs and medicine. Integrations with other tools are available.', 'Безмаркерне захоплення руху
Повне тіло, пальці й міміка
Кілька людей одночасно
Реальний час і постобробка
DARI для спорту й медицини', 'Markerless motion capture
Full body, fingers and faces
Multiple people at once
Real time and post-processing
DARI for sports and healthcare', 'Спортивні центри, клініки, студії анімації та розробники ігор.', 'Sports centers, clinics, animation studios and game developers.', 'desktop', 'course', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
