-- Carv — Аналіз техніки та біомеханіка
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'getcarv.com' OR LOWER(`name`) = LOWER('Carv'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Carv', NULL, 'https://getcarv.com', NULL, NULL, 'Carv — носимий гірськолижний тренер: датчики на черевиках аналізують тиск і рух, AI оцінює техніку на кожному спуску, а аудіопідказки в реальному часі допомагають виправити помилки вже на наступному спуску.', 'Carv is a wearable ski coach: boot sensors analyze pressure and motion, AI scores your technique on every run, and real-time audio tips help you fix mistakes on the very next run.', 'Carv перетворює звичайний гірськолижний черевик на персонального тренера. Користуватися просто: прикріпіть датчики Carv 2 до ременів черевиків — вони передають дані на телефон через Bluetooth, поки ви катаєтеся. Далі достатньо просто кататися: AI-аналіз відстежує кожен спуск, оцінює техніку за тиском і рухом та показує, що саме покращити. Під час катання звучать аудіопідказки в реальному часі, тож помилки можна виправляти одразу на наступному спуску. За опитуванням користувачів Carv, вони стали кататися краще, відчули більше мотивації та краще розуміють свою техніку. Пристрій підходить і новачкам, і досвідченим лижникам.', 'Carv turns any ski boot into a personal coach. It is simple to use: clip the Carv 2 sensors onto each boot strap — they send data to your phone via Bluetooth as you ski. Then just ski: AI analysis tracks every run, scores your technique from pressure and motion and shows exactly what to improve. While you ski, real-time audio tips help you fix mistakes on the very next run. In a survey of Carv skiers, users said they improved, felt more motivated and understood their technique better. It suits both beginners and experienced skiers.', 'Датчики на черевики з Bluetooth
AI-аналіз кожного спуску
Оцінка техніки за тиском і рухом
Аудіопідказки в реальному часі
Для новачків і досвідчених', 'Bluetooth boot sensors
AI analysis of every run
Technique score from pressure and motion
Real-time audio tips
For beginners and experts', 'Гірськолижники будь-якого рівня, які хочуть покращити техніку катання.', 'Skiers of any level who want to improve their technique.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
