-- Cycling Analytics — Аналіз техніки та біомеханіка
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'cyclinganalytics.com' OR LOWER(`name`) = LOWER('Cycling Analytics'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Cycling Analytics', NULL, 'https://www.cyclinganalytics.com', NULL, NULL, 'Cycling Analytics — програма для аналізу даних поїздок і керування тренуваннями велосипедистів: працює з вимірювачами потужності чи пульсометрами й більшістю велокомп''ютерів, календар, підсумки тижнів і місяців, плани.', 'Cycling Analytics is ride data analysis and training management software for cyclists: it works with power meters or heart rate monitors and most bike computers, with a calendar, weekly and monthly summaries and plans.', 'Cycling Analytics прагне бути глибоким, потужним і зручним інструментом для аналізу даних поїздок і керування тренуваннями. Щоб почати, потрібні велосипед, вимірювач потужності або пульсометр, велокомп''ютер (підтримується більшість пристроїв) і акаунт. Натомість ви отримуєте зрозумілий інтерфейс для всіх ваших поїздок: основні дані про кожен заїзд у календарі, підсумки за тижні й місяці, швидку навігацію до будь-якої дати, а також бібліотеку тренувальних планів і інструменти аналізу потужності. Сервіс допомагає бачити динаміку форми й планувати навантаження, не гублячись у сирих даних. Підходить і для аматорів, і для тренерів.', 'Cycling Analytics aims to be an insightful, powerful and user-friendly tool for analyzing ride data and managing training. To start you need a bike, a power meter or heart rate monitor, a bike computer (most devices are supported) and an account. In return you get a clean interface to all your riding: basic details of every ride on a calendar, weekly and monthly summaries, quick navigation to any date, a training plan library and power analysis tools. The service helps you see fitness trends and plan load without getting lost in raw data. It suits amateurs and coaches alike.', 'Аналіз даних потужності й пульсу
Календар поїздок
Підсумки за тижні й місяці
Бібліотека тренувальних планів
Підтримка більшості велокомп''ютерів', 'Power and heart rate analysis
Ride calendar
Weekly and monthly summaries
Training plan library
Support for most bike computers', 'Велосипедисти з вимірювачами потужності чи пульсометрами.', 'Cyclists with power meters or heart rate monitors.', 'web', 'basic', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
