-- DARI Motion — Аналіз техніки та біомеханіка
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'darimotion.com' OR LOWER(`name`) = LOWER('DARI Motion'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'DARI Motion', NULL, 'https://darimotion.com', NULL, NULL, 'DARI Motion — безмаркерний аналіз руху людини зі схваленням FDA: повний аналіз тіла за п''ять хвилин на основі технології Captury з валідованими даними для медицини, велнесу та спортивної продуктивності.', 'DARI Motion offers FDA-cleared markerless human motion analysis: a full-body analysis in five minutes built on Captury technology, with validated data for healthcare, wellness and sports performance.', 'DARI Motion — рішення для аналізу руху людини без маркерів, яке, за даними компанії, має схвалення FDA. Запатентована технологія спирається на програмне забезпечення захоплення руху від Captury і дозволяє оцінити рух людини за п''ять хвилин, отримавши валідовані дані та повний аналіз тіла. Це допомагає швидко й легко збирати дані, що ведуть до кращих результатів. Рішення поділено на три напрями: охорона здоров''я (покращення результатів лікування пацієнтів), велнес і спортивна продуктивність (оцінка атлетів, профілактика травм, повернення до спорту). На сайті є клінічні дослідження, блог, інформація про клієнтів і партнерів та запис на демонстрацію.', 'DARI Motion is a markerless human motion analysis solution that, according to the company, is FDA-cleared. The patented technology builds on Captury''s motion capture software and assesses human movement in five minutes with validated data and a full-body analysis. This makes it fast and easy to capture data that leads to better outcomes. Solutions cover three areas: healthcare (improving patient outcomes), wellness and sports performance (athlete assessment, injury prevention, return to play). The site has clinical studies, a blog, clients and partners and demo booking.', 'Безмаркерний аналіз руху
Повний аналіз тіла за 5 хвилин
Схвалення FDA
Медицина, велнес і спорт
Клінічні дослідження', 'Markerless motion analysis
Full-body analysis in 5 minutes
FDA clearance
Healthcare, wellness and sport
Clinical studies', 'Клініки, фізіотерапевти, спортивні команди й центри продуктивності.', 'Clinics, physical therapists, sports teams and performance centers.', 'desktop', 'basic', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
