SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'drdishbasketball.com' OR LOWER(`name`) = LOWER('Dr. Dish'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Dr. Dish', NULL, 'https://www.drdishbasketball.com', NULL, NULL, 'Dr. Dish — баскетбольні машини для кидків, що дають більше повторень і миттєвий зворотний зв''язок: Arc1 з відстеженням дуги кидка, CT+, All-Star+, Rebel+, домашні моделі й рішення для шкіл і залів. Є фінансування.', 'Dr. Dish makes basketball shooting machines that deliver more reps and instant feedback: Arc1 with shot arc tracking, CT+, All-Star+, Rebel+, home models and solutions for schools and facilities.', 'Dr. Dish виробляє машини для тренування кидків у баскетболі, які подають м''яч і дозволяють зробити значно більше повторень за тренування, отримуючи миттєвий зворотний зв''язок. Нова модель Arc1 — єдина машина для кидків із відстеженням дуги кидка. У лінійці також CT+, All-Star+, Rebel+, домашня Home3 і тренажер IC3, а для спортивних об''єктів — серія FCLTY. Компанія пропонує рішення для шкіл і залів, програму обміну старої машини, вживані машини, аксесуари, фінансування й планування платежів. На сайті є навчальні відео, розділ для тренерів, історії успіху та можливість отримати комерційну пропозицію з цінами.', 'Dr. Dish builds basketball shooting machines that feed the ball so players get many more reps per session with instant feedback. The new Arc1 is the only shooting machine with arc tracking. The lineup also includes CT+, All-Star+, Rebel+, the Home3 and the IC3 shot trainer, plus the FCLTY series for facilities. The company offers solutions for schools and gyms, a trade-in program, pre-owned machines, accessories, financing and payment plans. The site has training videos, a coaches corner, success stories and a form to request a pricing quote.', 'Машини для кидків із подачею м''яча
