SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'enode.ai' OR LOWER(`name`) = LOWER('Enode'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Enode', NULL, 'https://enode.ai', NULL, NULL, 'Enode — повне рішення для тренувань на основі швидкості (VBT): сенсори Enode One та Enode Pro відстежують швидкість штанги в реальному часі, застосунки допомагають призначати навантаження, а портал — стежити за атлетами.', 'Enode is a complete velocity-based training (VBT) solution: Enode One and Enode Pro sensors track bar speed in real time, apps help prescribe smarter loads, and a portal monitors every athlete.', 'Enode допомагає тренуватися точніше за допомогою вимірювання швидкості штанги. Сенсори Enode One та Enode Pro в реальному часі відстежують швидкість руху, а застосунки допомагають розумніше призначати навантаження, ґрунтуючись на фактичній швидкості, а не лише на відсотках від максимуму. Тренери можуть стежити за кожним атлетом через портал. Кожен тариф Enode Pro включає весь продукт; почати можна безплатно з трьома атлетами й переходити на Enode Pro+ лише тоді, коли потрібно більше атлетів чи станцій запису. Для тих, хто тренується самостійно, є окремий варіант. На сайті доступні гід для старту, довідка, блог і дані про валідність і надійність вимірювань.', 'Enode helps you train more precisely by measuring bar speed. The Enode One and Enode Pro sensors track movement velocity in real time, and the apps help prescribe smarter loads based on actual speed rather than just percentages of a max. Coaches can monitor every athlete through the portal. Every Enode Pro plan includes the whole product; you can start free with three athletes and move to Enode Pro+ only when you need more athletes or recording stations. There is a separate option for people training on their own. The site has a getting-started guide, help desk, blog and validity and reliability data.', 'Сенсори Enode One та Enode Pro
Швидкість штанги в реальному часі
Призначення навантаження за швидкістю
Портал для моніторингу атлетів
Безплатно до трьох атлетів
Дані про валідність', 'Enode One and Enode Pro sensors
Real-time bar speed
Velocity-based load prescription
Portal for athlete monitoring
Free for up to three athletes
Validity data', 'Тренери з фізпідготовки, команди й атлети, які тренуються самостійно.', 'Strength and conditioning coaches, teams and self-coached athletes.', 'mobile,web', 'basic', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
