-- Equisense — Аналіз техніки та біомеханіка
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'equisense.com' OR LOWER(`name`) = LOWER('Equisense'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Equisense', NULL, 'https://equisense.com', NULL, NULL, 'Equisense — підключені кріплення й сідельні ремені з сенсором Motion One для аналізу фізичної форми, локомоції та прогресу коня прямо в телефоні; французька технологія для вершників і тренерів. Ціна — 289 EUR.', 'Equisense makes connected attachments and girths with the Motion One sensor to analyze your horse''s fitness, locomotion and progress right on your phone; French technology for riders and coaches.', 'Equisense — французька компанія, що допомагає вершникам краще розуміти свого коня за допомогою даних. Сенсор Motion One кріпиться до спорядження чи підпруги й фіксує рух під час тренування. Застосунок аналізує фізичну форму, локомоцію та прогрес коня й показує результати просто в телефоні. Це допомагає планувати навантаження, помічати зміни в русі та відстежувати розвиток коня з часом. Сенсор доступний у кількох кольорах і з варіантами для різних країн, а магазин, застосунок, опис технології, історія компанії, партнери й блог представлені на сайті. Motion One коштує 289 EUR. Дані також допомагають ветеринарам і тренерам у спільній роботі.', 'Equisense is a French company that helps riders understand their horse better through data. The Motion One sensor attaches to tack or the girth and records movement during training. The app analyzes the horse''s fitness, locomotion and progress and shows the results right on your phone. This helps plan workload, notice changes in movement and track the horse''s development over time. The sensor comes in several colors and country versions, and the site presents the shop, app, technology, company story, partners and a blog. Motion One costs 289 EUR. The data also help vets and coaches work together.', 'Сенсор Motion One
Аналіз фізичної форми коня
Аналіз локомоції
Відстеження прогресу
Застосунок у телефоні', 'Motion One sensor
Horse fitness analysis
Locomotion analysis
Progress tracking
Phone app', 'Вершники, тренери й власники спортивних коней.', 'Riders, coaches and owners of sport horses.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
