INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Equisense is a French company that helps riders understand their horse better through data. The Motion One sensor attaches to tack or the girth and records movement during training. The app analyzes the horse''s fitness, locomotion and progress and shows the results right on your phone. This helps plan workload, notice changes in movement and track the horse''s development over time. The sensor comes in several colors and country versions, and the site presents the shop, app, technology, company story, partners and a blog. Motion One costs 289 EUR. The data also help vets and coaches work together.', 'manual' FROM DUAL WHERE @new = 1;
