SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'footbar.com' OR LOWER(`name`) = LOWER('Footbar'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Footbar', NULL, 'https://footbar.com', NULL, NULL, 'Footbar — трекер для футболістів будь-якого рівня: дані про гру одразу після сесії для формату 11×11, 5×5 чи футзалу, спеціальна футболка, підписка Footbar Gold, рукави й ремінці, а також пропозиція для клубів.', 'Footbar is a tracker for footballers of every level: performance data right after the session for 11-a-side, 5-a-side or futsal, a dedicated jersey, the Footbar Gold subscription, sleeves and straps, plus a club offer.', 'Footbar робить відстеження даних доступним усім футболістам. Невеликий трекер кріпиться на ногу за допомогою рукава або ремінця, а одразу після сесії застосунок показує показники вашої гри, щоб ви могли грати, вимірювати й прогресувати. Пристрій підходить для футболу 11 на 11, міні-футболу 5 на 5 і футзалу. Окрім трекера, є спеціальна футболка, підписка Footbar Gold з розширеними можливостями та аксесуари. Для клубів передбачена окрема пропозиція, що дозволяє відстежувати всю команду. На сайті доступні відповіді на часті запитання, інструкції та інформація про компанію. Дані допомагають зрозуміти, як змінюється ваша гра від матчу до матчу.', 'Footbar makes data tracking accessible to every footballer. A small tracker attaches to the leg with a sleeve or strap, and right after the session the app shows your performance metrics so you can play, measure and progress. The device works for 11-a-side, 5-a-side and futsal. Besides the tracker there is a dedicated jersey, the Footbar Gold subscription with extended features and accessories. Clubs get a dedicated offer for tracking the whole team. The site has FAQs, tutorials and company information. The data help you see how your game changes from match to match.', 'Трекер для футболістів
Дані одразу після сесії
