SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'fulltrack.ai' OR LOWER(`name`) = LOWER('Fulltrack AI'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Fulltrack AI', NULL, 'https://www.fulltrack.ai', NULL, NULL, 'Fulltrack AI — AI-відстеження м''яча й статистика для крикету лише з телефона: автоматичні кліпи, швидкість, свінг, оберт, DRS для LBW, карти подач і хайлайти баттера; від 9,99 USD на місяць замість дорогих систем.', 'Fulltrack AI offers AI ball tracking and stats for cricket from just a phone: auto-clipped videos, speed, swing, spin, DRS for LBW, pitch maps and batting highlights; from 9.99 USD a month instead of costly systems.', 'Fulltrack AI робить технології, які професіонали оплачують сотнями доларів за матч, доступними кожному гравцю в крикет. Достатньо смартфона: застосунок автоматично відстежує м''яч і рахує статистику, нарізає відео, вимірює швидкість, свінг і оберт, будує карти подач, а також пропонує систему перегляду рішень DRS для LBW. Для баттерів автоматично створюються хайлайти за лінією й довжиною подачі. Відео зберігаються в хмарі, економлячи пам''ять телефона, а сесією можна поділитися з командою в один клік. На матчах технологія усуває упередженість у рішеннях і залучає гравців даними. Для шкіл і клубів потрібна ліцензія Coach Plus, для професійних організацій — Enterprise; є безплатний пробний період.', 'Fulltrack AI makes technology that professionals pay hundreds of dollars per match for affordable to every cricketer. A smartphone is enough: the app automatically tracks the ball and records stats, clips video, measures speed, swing and spin, builds pitch maps and offers a DRS review system for LBWs. Batters get automatic highlights by line and length. Videos are stored in the cloud to save phone memory, and a session can be shared with teammates in one click. In matches the technology removes bias from decisions and engages players with data. Schools and clubs need a Coach Plus license and pro organizations an Enterprise license; a free trial is available.', 'AI-відстеження м''яча з телефона
Швидкість, свінг, оберт і карти подач
DRS для рішень LBW
Автоматичні хайлайти баттера
Хмарне зберігання
Ліцензії для клубів і профі', 'AI ball tracking from a phone
Speed, swing, spin and pitch maps
DRS for LBW decisions
Automatic batting highlights
Cloud storage
Licenses for clubs and pros', 'Гравці в крикет, тренери, школи та клуби.', 'Cricketers, coaches, schools and clubs.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
