-- GEARS Sports — Аналіз техніки та біомеханіка
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'gearssports.com' OR LOWER(`name`) = LOWER('GEARS Sports'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'GEARS Sports', NULL, 'https://www.gearssports.com', NULL, NULL, 'GEARS Sports — точна 3D-біомеханіка й аналітика руху для гольфу, волейболу, бігу, бейсболу, футболу, американського футболу й баскетболу: еталонні показники атлетів на піку форми для подальшого порівняння.', 'GEARS Sports offers precise 3D biomechanics and motion analytics for golf, volleyball, running, baseball, soccer, football and basketball, benchmarking athletes at their peak for future comparison.', 'GEARS Sports створює системи аналізу руху, у яких головне — точність. Технологія фіксує рух спортсмена в 3D і дає поглиблену аналітику, що допомагає вийти на новий рівень. Особливо корисно фіксувати еталонні показники, коли атлет перебуває на піку форми, щоб потім порівнювати з ними й оцінювати зміни. Найбільше система відома в гольфі, але підтримує також волейбол, біг, бейсбол, футбол, американський футбол і баскетбол. Рішення 3DX Performance розкриває можливості для професійної роботи. На сайті є відео підтримки, статті, адреси локацій із системою GEARS, магазин і можливість фінансування. Системи встановлюють у спеціалізованих тренувальних центрах.', 'GEARS Sports builds motion analysis systems where accuracy matters most. The technology captures athlete movement in 3D and provides in-depth analytics that help athletes reach the next level. It is especially useful to benchmark athletes when they are at the top of their game so you can compare against it later and evaluate changes. The system is best known in golf but also supports volleyball, running, baseball, soccer, football and basketball. The 3DX Performance solution opens up professional workflows. The site has support videos, articles, locations with GEARS systems, a shop and financing. Systems are installed in specialized training centers.', 'Точне 3D-захоплення руху
Поглиблена біомеханічна аналітика
Еталонні показники атлетів
Гольф та інші види спорту
3DX Performance
Фінансування', 'Precise 3D motion capture
In-depth biomechanics analytics
Athlete benchmarking
Golf and other sports
3DX Performance
Financing', 'Гольф-тренери, спортивні лабораторії та центри підготовки атлетів.', 'Golf coaches, sports labs and athlete development centers.', 'desktop', 'course', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
