-- GoldenCheetah — Аналіз техніки та біомеханіка
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'goldencheetah.org' OR LOWER(`name`) = LOWER('GoldenCheetah'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'GoldenCheetah', NULL, 'https://www.goldencheetah.org', NULL, NULL, 'GoldenCheetah — безплатна програма з відкритим кодом для аналізу даних потужності велосипедистів і тріатлоністів: імпорт з Garmin, SRM, PowerTap та інших, широкий набір інструментів аналізу для Linux, macOS і Windows.', 'GoldenCheetah is free, open-source power data analysis software for cyclists and triathletes: import from Garmin, SRM, PowerTap and more, with a rich set of analysis tools for Linux, macOS and Windows.', 'GoldenCheetah виходить з переконання, що велосипедисти й тріатлоністи повинні мати змогу завантажувати власні дані потужності на комп''ютер і аналізувати їх без обмежень. Програма завантажує або імпортує дані поїздок безпосередньо з багатьох пристроїв Garmin, SRM, PowerTap, O_Synce, а також файли з програм інших виробників і TrainingPeaks WKO+. Вона пропонує багатий набір інструментів аналізу — від кривих потужності до моделей навантаження й відновлення. GoldenCheetah працює на Linux, macOS і Windows, поширюється під відкритою ліцензією й розвивається спільнотою розробників. На сайті є завантаження, опис функцій, уроки та наукові матеріали.', 'GoldenCheetah starts from the belief that cyclists and triathletes should be able to download their power data to their own computer and analyze it without restrictions. It downloads or imports ride data directly from many Garmin, SRM, PowerTap and O_Synce devices, as well as files from other manufacturers'' software and TrainingPeaks WKO+. It offers a rich set of analysis tools — from power curves to load and recovery models. GoldenCheetah runs on Linux, macOS and Windows, is released under an open-source license and is developed by a community of contributors. The site has downloads, features, tutorials and science resources.', 'Імпорт даних з Garmin, SRM, PowerTap
Аналіз потужності й навантаження
Моделі втоми й відновлення
Linux, macOS і Windows
Відкритий код
Безплатно', 'Import from Garmin, SRM, PowerTap
Power and load analysis
Fatigue and recovery models
Linux, macOS and Windows
Open source
Free', 'Велосипедисти, тріатлоністи й тренери, які аналізують дані потужності.', 'Cyclists, triathletes and coaches analyzing power data.', 'desktop', 'basic', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
