SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'hackmotion.com' OR LOWER(`name`) = LOWER('HackMotion'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'HackMotion', NULL, 'https://hackmotion.com', NULL, NULL, 'HackMotion — система зворотного зв''язку для свінгу в гольфі: сенсор на зап''ясті й мобільний застосунок вимірюють кути зап''ястя та перетворюють рух на живі поради, допомагаючи контролювати грань ключки й політ м''яча.', 'HackMotion is a golf swing feedback system: a wrist sensor and mobile app measure wrist angles and turn movement into live coaching advice, helping you control the clubface and ball flight.', 'HackMotion виходить з того, що неможливо виправити те, чого не можна виміряти: помилки свінгу часто походять від рухів, які не видно й не відчуваються точно, тому прогрес буває повільним і нестабільним. Система складається із сенсора на зап''ясті та мобільного застосунку, які перетворюють ваш рух на живі поради тренера. Практика складається з чотирьох простих кроків: ви надягаєте сенсор і вимірюєте свінг, фіксуєте кути зап''ястя, отримуєте зворотний зв''язок і тренуєтеся, поки рух не стане стабільним. Це допомагає виправити типові помилки, покращити політ м''яча й опанувати контроль грані ключки. Доступне четверте покоління сенсора.', 'HackMotion starts from the idea that you can''t fix what you can''t measure: swing faults often come from movements you can''t see or accurately feel, so progress can be slow and inconsistent. The system is a wrist sensor plus a mobile app that turn your movement into live coaching advice. Practice follows four easy steps: wear the sensor and measure your swing, capture your wrist angles, get feedback and train until the movement is consistent. This helps fix common swing faults, improve ball flight and master clubface control. The fourth-generation sensor is now available.', 'Сенсор кутів зап''ястя
