-- HELIOS Hockey — Аналіз техніки та біомеханіка
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'helioshockey.com' OR LOWER(`name`) = LOWER('HELIOS Hockey'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'HELIOS Hockey', NULL, 'https://helioshockey.com', NULL, NULL, 'HELIOS — сенсор і застосунок для хокеїстів: реальні дані про катання й навантаження, миттєве відео змін, порівняння з гравцями свого року народження, відстеження покращень і рекомендації для тренувань.', 'HELIOS is a sensor and app for hockey players: real skating and workload data, instant shift video, comparison with players of your birth year, improvement tracking and training recommendations.', 'HELIOS допомагає хокеїстам вимірювати те, що має значення, і вигравати більше змін. Сенсор фіксує реальні дані про катання та навантаження, щоб тренуватися цілеспрямовано. Технологія генерує миттєве відео кожної зміни, показує місце гравця серед однолітків свого року народження, відстежує покращення та дає рекомендації для тренувань. Є окремі рішення для гравців і команд. Членство PRO включає сенсор, кріплення, бездротовий зарядний пристрій і довічну гарантію; оплачувати можна помісячно із сезонним зобов''язанням, за рік або за два роки зі знижкою. Річне членство коштує 249 USD, дворічне — 399 USD, помісячне — 29 USD на місяць.', 'HELIOS helps hockey players measure what matters and win more shifts. The sensor captures real skating and workload data so you can train with purpose. The technology generates instant shift video, shows where a player stands among peers of the same birth year, tracks improvement and delivers training recommendations. There are dedicated options for players and teams. The PRO membership includes the core sensor, mounts, a wireless charger and a lifetime warranty; you can pay monthly with a season commitment, annually or every two years at a discount. The annual membership is 249 USD, two years is 399 USD and monthly is 29 USD.', 'Дані про катання й навантаження
