SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'hittrax.com' OR LOWER(`name`) = LOWER('HitTrax'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'HitTrax', NULL, 'https://www.hittrax.com', NULL, NULL, 'HitTrax — технологія для бейсболу й софтболу з відстеженням м''яча комп''ютерним зором: HitTrax Pro для розвитку атлетів, HitTrax Home для тренувань і онлайн-гри вдома, HitTrax Suite для барів і спортивних розваг.', 'HitTrax is baseball and softball technology with computer-vision ball tracking: HitTrax Pro for athlete development, HitTrax Home for training and online play at home, and HitTrax Suite for bars and social sports.', 'HitTrax пропонує технології аналізу продуктивності в бейсболі та софтболі з даними й інсайтами в реальному часі. HitTrax Pro поєднує відстеження м''яча комп''ютерним зором, миттєвий зворотний зв''язок і захопливу аналітику для розвитку спортсменів. HitTrax Home переносить професійні тренування у ваш простір: можна відточувати навички, змагатися з друзями й грати онлайн у будь-який час. HitTrax Suite адаптує професійне відстеження та ігровий процес у готовий розважальний формат для барів, закладів і соціального спорту. На сайті є магазин обладнання й одягу, новини та інсайти, а також окремі розділи для тренувань і розваг.', 'HitTrax offers performance analysis technology for baseball and softball with real-time data and insights. HitTrax Pro combines computer-vision ball tracking, instant feedback and engaging performance insights for athlete development. HitTrax Home brings pro training into your own space: sharpen skills, compete with friends and play online anytime. HitTrax Suite adapts pro-level tracking and gameplay into a turnkey entertainment experience for bars, venues and social sports. The site has a hardware and apparel shop, news and insights, and separate training and entertainment sections.', 'Відстеження м''яча комп''ютерним зором
