SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'intelligym.com' OR LOWER(`name`) = LOWER('IntelliGym'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'IntelliGym', NULL, 'https://www.intelligym.com', NULL, NULL, 'IntelliGym — тренування ігрового інтелекту на основі нейронауки: цифрова арена імітує реальну гру, щоб гравці краще адаптувалися до мінливих ситуацій; версії Soccer IntelliGym і Hockey IntelliGym, нові види на підході.', 'IntelliGym is neuroscience-based game intelligence training: a digital arena simulates real gameplay so players adapt better to shifting situations; Soccer IntelliGym and Hockey IntelliGym, with more sports coming.', 'IntelliGym допомагає тренувати мозок, як це роблять професіонали. Платформа, що спирається на технології з нейронауки, імітує реальний ігровий процес у цифровій арені, щоб гравці краще пристосовувалися до швидких змін ситуації в реальному спорті. Мета — розвиток ігрового інтелекту: сприйняття, передбачення, ухвалення рішень і командної взаємодії. Наразі доступні Soccer IntelliGym для футболу та Hockey IntelliGym для хокею, а програми для інших видів спорту готуються. На сайті пояснюється наукове підґрунтя методу, є блог і інформація про компанію. Розробники наголошують, що ключ до перемоги — у голові гравця.', 'IntelliGym helps you train your brain like a pro. Based on advanced neuroscience technology, the platform simulates actual gameplay in a digital arena so players adapt better to the shifting realities of real-time sports. The goal is to develop game intelligence: perception, anticipation, decision-making and team play. Soccer IntelliGym and Hockey IntelliGym are available now, with programs for other sports in the works. The site explains the science behind the method and has a blog and company information. The developers emphasize that the key to winning is in the player''s head.', 'Тренування ігрового інтелекту
Цифрова арена з імітацією гри
Soccer IntelliGym
Hockey IntelliGym
Науково обґрунтований метод', 'Game intelligence training
