-- Kinetisense — Аналіз техніки та біомеханіка
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'kinetisense.com' OR LOWER(`name`) = LOWER('Kinetisense'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Kinetisense', NULL, 'https://www.kinetisense.com', NULL, NULL, 'Kinetisense — безмаркерне захоплення руху для клінік і клубів: оцінка руху за дві хвилини на iPad, наочні результати для пацієнтів; для ортопедів, фізіотерапевтів, хіропрактиків, спортивної продуктивності й робочих місць.', 'Kinetisense offers markerless motion capture for clinics and clubs: a movement assessment in two minutes on an iPad, clear results for patients; for orthopedists, physical therapists, chiropractors, sports performance and workplaces.', 'Kinetisense допомагає клініцистам і тренерам показати пацієнту чи спортсмену те, що раніше доводилося описувати словами. Одна оцінка руху займає близько двох хвилин і проводиться на iPad, який у вас уже є, у тому самому кабінеті — без маркерів і спеціальної лабораторії. Наочні результати полегшують розмову, підвищують дотримання плану й скорочують робочий день. Рішення розраховане на ортопедів, фізіотерапевтів, хіропрактиків, масажистів, програми активного старіння, ветеранів, оцінку на робочих місцях і спортивну продуктивність. Технологією користуються, зокрема, Повітряні сили США. Дані зберігаються в Kinetisense Vault, а на сайті можна записатися на 15-хвилинну демонстрацію.', 'Kinetisense helps clinicians and coaches show patients or athletes what they used to have to describe in words. One movement assessment takes about two minutes on the iPad you already own, in the room you already use — no markers or special lab. Clear results make conversations easier, improve plan adherence and shorten the working day. It serves orthopedic specialists, physical therapists, chiropractors, massage therapists, active aging programs, veteran care, workplace assessments and sports performance. The technology is used by organizations including the U.S. Air Force. Data are stored in the Kinetisense Vault, and you can book a 15-minute demo on the site.', 'Безмаркерна оцінка руху на iPad
Результат за дві хвилини
Наочні звіти для пацієнтів
Клініка, спорт і робочі місця
Сховище даних Vault', 'Markerless movement assessment on iPad
Results in two minutes
Visual reports for patients
Clinical, sports and workplace
Vault data storage', 'Фізіотерапевти, ортопеди, хіропрактики, спортивні клуби й фахівці з охорони праці.', 'Physical therapists, orthopedists, chiropractors, sports clubs and occupational health specialists.', 'mobile', 'basic', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
