-- Kinovea — Аналіз техніки та біомеханіка
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'kinovea.org' OR LOWER(`name`) = LOWER('Kinovea'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Kinovea', NULL, 'https://www.kinovea.org', NULL, NULL, 'Kinovea — безплатна програма з відкритим кодом для відеоаналізу в спорті: захоплення, сповільнення, порівняння двох відео поруч, анотації, відстеження руху та вимірювання кутів, відстаней і часу на відео.', 'Kinovea is free, open-source video analysis software for sport: capture, slow down, compare two videos side by side, annotate, track motion and measure angles, distances and time on video.', 'Kinovea — це «мікроскоп для ваших відео», інструмент анотації, створений для аналізу в спорті. Програма дозволяє захоплювати відео, сповільнювати його, порівнювати, додавати анотації, відстежувати й вимірювати рух. Можна збагачувати відео стрілками, описами та іншим контентом у ключових позиціях, переглядати два відео поруч і синхронізувати їх за спільною подією, вимірювати кути, відстані й час. Розробники прагнуть, щоб програма була достатньо простою для навчального класу й достатньо потужною для олімпійської підготовки. Kinovea повністю безплатна й має відкритий вихідний код; доступні завантаження, довідка й форум.', 'Kinovea is a microscope for your videos — an annotation tool designed for sport analysis. It lets you capture, slow down, compare, annotate, track and measure motion in videos. You can enrich footage with arrows, descriptions and other content at key positions, watch two videos side by side synchronized on a common event, and measure angles, distances and time. The developers aim to make it simple enough for the classroom and powerful enough for Olympic training. Kinovea is completely free and open source, with downloads, help and a forum.', 'Сповільнене відтворення й захоплення
Порівняння двох відео поруч
Анотації на відео
Відстеження руху
Вимірювання кутів і відстаней
Безплатно й відкритий код', 'Slow motion and capture
Side-by-side video comparison
Video annotations
Motion tracking
Angle and distance measurement
Free and open source', 'Тренери, спортсмени, викладачі фізкультури, фізіотерапевти й дослідники.', 'Coaches, athletes, PE teachers, physiotherapists and researchers.', 'desktop', 'basic', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
