-- Metric — Аналіз техніки та біомеханіка
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'metric.coach' OR LOWER(`name`) = LOWER('Metric'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Metric', NULL, 'https://metric.coach', NULL, NULL, 'Metric — вимірювання продуктивності камерою телефона без додаткового обладнання: швидкість штанги, потужність і 1ПМ у Metric Lift, висота стрибка й RSI в Metric Jump, спринт і спритність у Metric Sprint, програми для команд.', 'Metric measures performance with your phone camera and no extra hardware: bar speed, power and 1RM in Metric Lift, jump height and RSI in Metric Jump, sprint and agility in Metric Sprint, plus programs for teams.', 'Metric об''єднує весь тренувальний стек в одному місці: можна ділитися програмами, записувати тренування й тестувати продуктивність там, де тренуються атлети. Для цього не потрібні сенсори чи ворота — достатньо камери телефона. Metric Lift вимірює швидкість штанги, потужність і оцінює одноповторний максимум у кожному повторенні, плануючи й записуючи тренування. Metric Jump (лише iOS) автоматично визначає висоту стрибка, імпульс, швидкість, RSI та симетрію лівої й правої сторони. Metric Sprint (лише iOS) повністю автоматично вимірює спринт і спритність. Підписка Metric Ultra відкриває Pro в усіх трьох застосунках: Solo для одного атлета коштує 89,99 USD на рік, а Coach масштабується на команду.', 'Metric brings your whole training stack into one place: share programs, log workouts and test performance wherever athletes train. No sensors or gates are needed — just a phone camera. Metric Lift measures bar speed, power and estimated one-rep max on every rep while planning and logging workouts. Metric Jump (iOS only) automatically measures jump height, impulse, velocity, RSI and left–right symmetry. Metric Sprint (iOS only) provides fully automatic sprint and agility timing. The Metric Ultra subscription unlocks Pro across all three apps: Solo for one athlete costs 89.99 USD per year, and Coach scales to a whole roster.', 'Швидкість штанги й 1ПМ камерою
Висота стрибка, RSI і симетрія
Спринт і спритність без воріт
Програми й журнал тренувань
План Coach для команд
Без додаткового обладнання', 'Bar speed and 1RM via camera
Jump height, RSI and symmetry
Sprint and agility without gates
Programs and workout log
Coach plan for teams
No extra hardware', 'Силові атлети, тренери з фізпідготовки та спортивні команди.', 'Strength athletes, strength and conditioning coaches and sports teams.', 'mobile,web', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
