SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'move.ai' OR LOWER(`name`) = LOWER('Move AI'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Move AI', NULL, 'https://www.move.ai', NULL, NULL, 'Move AI — безмаркерне захоплення руху з відео на основі AI: багатокамерні системи й платформа Move One для високоточної 3D-анімації, що прискорюють виробництво й знижують витрати для студій, ігор і спортивного аналізу.', 'Move AI offers AI-powered markerless motion capture from video: multi-camera systems and the Move One platform for high-fidelity 3D animation that speeds production and cuts costs for studios, games and movement analysis.', 'Move AI розвиває безмаркерне захоплення руху з 2019 року. Компанія створила перші в галузі багатокамерні системи й запатентувала штучний інтелект свого рушія руху. Технологія перетворює звичайне відео на високоякісну 3D-анімацію, що прискорює виробництво й знижує витрати порівняно з костюмами й маркерами. Системи Move використовують провідні компанії у VFX, розвагах та іграх, а на сайті окремо розкриті технологія, точність, аналітичні інсайти й кейси. Платформа Move One дає доступ до захоплення руху без складного обладнання, а для професійних студій можна зібрати власну систему. Доступні документація й демонстрація.', 'Move AI has pioneered markerless motion capture since 2019. The company invented the industry''s first multi-camera systems and patented the artificial intelligence behind its motion engine. The technology turns ordinary video into high-fidelity 3D animation, speeding up production and reducing costs compared with suits and markers. Move systems are used by leading companies in VFX, entertainment and gaming, and the site covers the tech, accuracy, insights and case studies. The Move One platform provides motion capture without complex hardware, and professional studios can build their own system. Docs and demos are available.', 'Безмаркерне захоплення руху з відео
Багатокамерні системи
Запатентований AI-рушій руху
Платформа Move One
Висока точність 3D-анімації', 'Markerless motion capture from video
Multi-camera systems
Patented AI motion engine
Move One platform
High-accuracy 3D animation', 'Студії анімації, розробники ігор, VFX-команди та аналітики руху.', 'Animation studios, game developers, VFX teams and movement analysts.', 'web,desktop', 'basic', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
