-- NeuroTracker — Аналіз техніки та біомеханіка
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'neurotrackerx.com' OR LOWER(`name`) = LOWER('NeuroTracker'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'NeuroTracker', NULL, 'https://www.neurotrackerx.com', NULL, NULL, 'NeuroTracker — система когнітивних тренувань, побудована на 20 роках нейронаукових досліджень: розвиває сприйняття руху, увагу, багатозадачність і реакцію для баскетболу, хокею, футболу, єдиноборств та інших видів.', 'NeuroTracker is a cognitive training system built on 20 years of neuroscience research: it develops motion perception, attention, multitasking and response control for basketball, hockey, football, combat sports and more.', 'NeuroTracker — система тренування мозку, створена на основі двох десятиліть нейронаукових досліджень. У спорті її використовують, щоб покращити сприйняття руху, просторову обізнаність, багатозадачність, контроль реакції, здатність до навчання, рухову продуктивність і стійкість до втоми, а також для профілактики травм. Програми адаптовано для баскетболу, хокею, американського футболу й футболу, єдиноборств, регбі, бейсболу, легкої атлетики, кіберспорту, військових і правоохоронців. Окремі напрями охоплюють велнес і освіту (СДУГ, безпека водіння, стрес), медицину й реабілітацію після струсів і травм. Можна пройти оцінку мозку та записатися на консультацію.', 'NeuroTracker is a brain training system built on two decades of neuroscience research. In sport it is used to improve motion perception, spatial awareness, multitasking, response control, learning capacity, motor performance and fatigue resistance, as well as for injury prevention. Programs are adapted for basketball, hockey, football and soccer, combat sports, rugby, baseball, athletics, gaming, military and law enforcement. Other tracks cover wellness and education (ADHD, driving safety, stress) and medicine and rehabilitation after concussions and injuries. You can take a brain assessment and book a call.', 'Когнітивні тренування для спортсменів
Сприйняття руху й багатозадачність
Стійкість до втоми й реакція
Програми для різних видів спорту
Реабілітація після струсів
Оцінка мозку', 'Cognitive training for athletes
Motion perception and multitasking
Fatigue resistance and response control
Programs for many sports
Concussion rehabilitation
Brain assessment', 'Спортсмени, команди, кіберспортсмени, а також фахівці з реабілітації.', 'Athletes, teams, esports players and rehabilitation specialists.', 'web,desktop', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
