-- Noraxon — Аналіз техніки та біомеханіка
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'noraxon.com' OR LOWER(`name`) = LOWER('Noraxon'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Noraxon', NULL, 'https://www.noraxon.com', NULL, NULL, 'Noraxon — інтегровані технології аналізу руху для досліджень, клініки, спорту й ергономіки: поверхнева ЕМГ, 3D-захоплення руху, 2D-камери, силові платформи, доріжки з датчиками тиску, устілки й ПЗ MR4.', 'Noraxon offers integrated movement analysis technology for research, clinical, sports and ergonomics: surface EMG, 3D motion capture, 2D cameras, force plates, pressure treadmills, insoles and MR4 software.', 'Noraxon створює інструменти біомеханіки, що спрощують аналіз руху й допомагають покращувати результати в дослідженнях, клінічній практиці, спорті та ергономіці. Лінійка включає поверхневу електроміографію (ЕМГ) із застосунком біофідбеку, бездротові датчики Ultium SmartLeads, 3D-захоплення руху, 2D-відеокамери, портативну лабораторію Ultium, силові платформи, бігові доріжки з датчиками тиску й сили, платформи й доріжки тиску, інструментовані устілки, реабілітаційні доріжки та систему аналогових входів. Усі дані об''єднуються в програмному забезпеченні MR4. Компанія надає підтримку, базу знань, академічні ресурси, кейси та навчальні заходи.', 'Noraxon builds biomechanics tools that simplify movement analysis and improve outcomes in research, clinical practice, sports and ergonomics. The lineup includes surface electromyography (EMG) with a biofeedback app, Ultium SmartLeads wireless sensors, 3D motion capture, 2D video cameras, the Ultium portable lab, force plates, pressure and force treadmills, pressure platforms and walkways, instrumented insoles, rehab treadmills and an analog input system. All data come together in the MR4 software. The company provides support, a knowledge base, academic resources, case studies and training events.', 'Поверхнева ЕМГ і біофідбек
3D-захоплення руху й 2D-камери
Силові платформи
Доріжки й устілки з датчиками
Портативна лабораторія
ПЗ MR4', 'Surface EMG and biofeedback
3D motion capture and 2D cameras
Force plates
Sensor treadmills and insoles
Portable lab
MR4 software', 'Дослідники, клініцисти, спортивні науковці й фахівці з ергономіки.', 'Researchers, clinicians, sports scientists and ergonomics specialists.', 'desktop', 'course', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
