-- Notio — Аналіз техніки та біомеханіка
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'notio.ai' OR LOWER(`name`) = LOWER('Notio'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Notio', NULL, 'https://notio.ai', NULL, NULL, 'Notio — пристрій і застосунок для велосипедистів, що в реальному часі розраховує аеродинамічний коефіцієнт і продуктивність на велосипеді, допомагаючи знайти оптимальну посадку й спорядження та їхати швидше й далі.', 'Notio is a device and app for cyclists that calculates your aerodynamic coefficient and on-bike performance in real time, helping you find the optimal position and gear to ride faster and further.', 'Notio перетворює швидкість на науку. Розумний пристрій кріпиться на велосипед і в реальному часі розраховує аеродинамічний опір і показники продуктивності, а застосунок допомагає перетворити цифри на рішення щодо техніки, посадки й спорядження, щоб знайти свою ідеальну позицію. Це особливо корисно для гонок на час і тріатлону, де аеродинаміка відіграє велику роль. Дані можна аналізувати в Golden Cheetah. На сайті є коротка інструкція для старту, відповіді на запитання, блог з історіями гонщиків, інформація про дистриб''юторів, гарантію та умови використання. Підтримку продукту зараз здійснює Argon 18.', 'Notio turns speed into science. The smart device mounts on the bike and calculates aerodynamic drag and performance metrics in real time, while the app helps turn the numbers into decisions about technique, position and equipment so you can find your sweet spot. This is especially useful for time trials and triathlon, where aerodynamics matter a lot. Data can be analyzed in Golden Cheetah. The site has a quick start guide, FAQs, a blog with rider stories, distributor information, warranty and terms. Product support is now provided by Argon 18.', 'Розрахунок аеродинамічного опору
Продуктивність у реальному часі
Підбір посадки й спорядження
Аналіз у Golden Cheetah
Для гонок на час і тріатлону', 'Aerodynamic drag calculation
Real-time performance
Position and gear optimization
Analysis in Golden Cheetah
For time trials and triathlon', 'Шосейні гонщики, тріатлоністи й велосипедисти, які працюють над аеродинамікою.', 'Road racers, triathletes and cyclists working on aerodynamics.', 'mobile', 'basic', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
