SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'opencap.ai' OR LOWER(`name`) = LOWER('OpenCap'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'OpenCap', NULL, 'https://www.opencap.ai', NULL, NULL, 'OpenCap — безплатне ПЗ з відкритим кодом для безмаркерного аналізу руху людини: 3D-рух і сили зі смартфонних відео, налаштування менш ніж за 2 хвилини, багатокамерний режим із iPhone і новий монокулярний режим.', 'OpenCap is free, open-source software for markerless human movement analysis: 3D motion and forces from smartphone video, under 2 minutes of setup, a multi-camera iPhone mode and a new monocular mode.', 'OpenCap дозволяє отримувати 3D-рух людини та сили, що на неї діють, із відео зі смартфонів — без маркерів і дорогої лабораторії. Налаштування займає менше двох хвилин. Є два способи запису. Багатокамерний режим дає найвищу точність: потрібні два чи більше iPhone і ще один пристрій для вебзастосунку — ви скануєте QR-код, калібруєте систему й записуєте. Монокулярний режим, що перебуває в бета-версії, є найпростішим: для запису достатньо одного iPhone. На сайті є приклади спортивної, реабілітаційної та монокулярної сесій, поради з налаштування, усунення несправностей, форум і наукова стаття. Код відкритий, а для досліджень сервіс безплатний.', 'OpenCap lets you get 3D human motion and the forces acting on the body from smartphone video — without markers or an expensive lab. Setup takes less than two minutes. There are two ways to record. The multi-camera setup gives the highest accuracy: you need two or more iPhones and one device for the web app — scan a QR code, calibrate and record. The monocular setup, in beta, is the simplest: a single iPhone is enough. The site has example sports, rehab and monocular sessions, best practices, troubleshooting, a forum and the research paper. The code is open and the service is free for research.', '3D-рух і сили зі смартфонних відео
Налаштування менш ніж за 2 хвилини
Багатокамерний режим на iPhone
Монокулярний режим (бета)
Відкритий код
Безплатно для досліджень', '3D motion and forces from phone video
Under 2 minutes of setup
Multi-camera iPhone mode
Monocular mode (beta)
Open source
Free for research', 'Біомеханіки, фізіотерапевти, спортивні науковці й дослідники.', 'Biomechanists, physiotherapists, sports scientists and researchers.', 'web,mobile', 'basic', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
