-- OptiTrack — Аналіз техніки та біомеханіка
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'optitrack.com' OR LOWER(`name`) = LOWER('OptiTrack'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'OptiTrack', NULL, 'https://optitrack.com', NULL, NULL, 'OptiTrack — системи оптичного захоплення руху з субміліметровою точністю й надійним відстеженням у реальному часі для дослідників, інженерів і творців; камери, ПЗ, аксесуари та нові активні маркери ActiveIO.', 'OptiTrack makes optical motion capture systems with sub-millimeter accuracy and reliable real-time tracking for researchers, engineers and creators; cameras, software, accessories and new ActiveIO active markers.', 'OptiTrack створює системи захоплення руху, що стали стандартом точності: субміліметрова точність і надійне відстеження в реальному часі для дослідників, інженерів, творців контенту й інноваторів. Компанія проєктує й виробляє камери, програмне забезпечення та аксесуари, а на сайті можна зібрати власну систему під конкретні задачі. Нова технологія ActiveIO пропонує розумні маркери, що самі себе ідентифікують, — наступне покоління активного відстеження. Системи OptiTrack застосовують у біомеханіці та спортивній науці, робототехніці, віртуальній реальності, кіно й анімації. Доступні підтримка, документація й консультації з вибору обладнання.', 'OptiTrack builds motion capture systems that set the standard for precision: sub-millimeter accuracy and reliable real-time tracking for researchers, engineers, creators and innovators. The company designs and manufactures its cameras, software and accessories, and the site lets you build a system for your needs. The new ActiveIO technology offers smart, self-identifying markers — the next generation of active tracking. OptiTrack systems are used in biomechanics and sports science, robotics, virtual reality, film and animation. Support, documentation and equipment advice are available.', 'Субміліметрова точність
Відстеження в реальному часі
