SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'pb.vision' OR LOWER(`name`) = LOWER('PB Vision'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'PB Vision', NULL, 'https://pb.vision', NULL, NULL, 'PB Vision — AI-аналіз відео в пікболі: завантажте запис гри в одиночному чи парному розряді й отримайте статистику кожного удару, шість AI-оцінок навичок, хайлайти та поради AI Coach; перша гра безплатно.', 'PB Vision is AI video analysis for pickleball: upload a singles or doubles game and get shot-by-shot stats, six AI skill ratings, highlights and AI Coach advice; the first game is free.', 'PB Vision перетворює кожну записану гру в пікбол на урок. Запишіть повну одиночну чи парну гру, завантажте відео й отримайте статистику кожного удару, оцінки навичок і хайлайти. Сервіс виставляє шість AI-оцінок за напрямами: гра біля кухні (зона біля сітки), контроль м''яча, захист, атака, ігровий інтелект і точність розміщення. Після аналізу можна запитати AI Coach, над чим працювати далі, і переглянути відповідні епізоди. Аналіз першої гри безплатний без картки, а в галереї доступні демо-приклади. Преміум-підписка відкриває регулярний аналіз; на акціях до річної підписки додають штатив для зйомки.', 'PB Vision turns every recorded pickleball game into a lesson. Record a complete singles or doubles game, upload it and get shot-by-shot stats, skill ratings and highlights. The service gives six AI skill ratings: kitchen game, ball control, defense, offense, court IQ and targeting. After the analysis you can ask the AI Coach what to work on next and review the relevant shots. Your first game analysis is free with no credit card, and a demo gallery shows examples. A Premium subscription unlocks regular analysis; promotions add a free tripod to annual plans.', 'Статистика кожного удару
Шість AI-оцінок навичок
Хайлайти гри
