-- Pivo — Аналіз техніки та біомеханіка
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'pivo.ai' OR LOWER(`name`) = LOWER('Pivo'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Pivo', NULL, 'https://pivo.ai', NULL, NULL, 'Pivo перетворює смартфон на камеру з автоматичним відстеженням на 360°: стежить за обличчям, тілом, конем чи собакою, щоб записувати себе без рук; набори для кінного спорту, Pivo Sports Pack і сервіс Pivo+.', 'Pivo turns your smartphone into a 360° auto-tracking camera that follows your face, body, horse or dog so you can record hands-free; equestrian kits, the Pivo Sports Pack and the Pivo+ service.', 'Pivo — поворотна підставка для смартфона, яка разом із застосунком перетворює телефон на камеру з автоматичним відстеженням. Пристрій обертається на 360° і стежить за обличчям, тілом, конем або собакою, тож можна знімати себе без оператора й без рук. Найпопулярніший напрям — кінний спорт: спеціальні набори для вершників дозволяють записувати тренування в манежі й потім аналізувати їзду. Для інших видів спорту є Pivo Sports Pack, що допомагає знімати тренування й ігри. Також пристрій використовують для професійної зйомки, нерухомості й бізнесу. Сервіс Pivo+ розширює можливості застосунку, а центр підтримки допомагає з налаштуванням.', 'Pivo is a rotating smartphone mount that, together with its app, turns your phone into an auto-tracking camera. The device rotates 360° and follows a face, body, horse or dog, so you can film yourself without a camera operator and hands-free. The most popular use is equestrian: dedicated rider kits let you record arena sessions and analyze your riding afterwards. For other sports there is the Pivo Sports Pack for filming training and games. The device is also used for professional content, real estate and business. The Pivo+ service extends the app''s features, and a support hub helps with setup.', 'Автовідстеження на 360°
Стеження за обличчям, тілом, конем
Набори для кінного спорту
Pivo Sports Pack
Сервіс Pivo+', '360° auto tracking
Follows faces, bodies and horses
Equestrian kits
Pivo Sports Pack
Pivo+ service', 'Вершники, спортсмени й тренери, які хочуть знімати тренування самостійно.', 'Riders, athletes and coaches who want to film training on their own.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
