SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'pocketradar.com' OR LOWER(`name`) = LOWER('Pocket Radar'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Pocket Radar', NULL, 'https://www.pocketradar.com', NULL, NULL, 'Pocket Radar — портативні радари швидкості для бейсболу, софтболу та інших видів спорту: вимірювання швидкості подачі й вильоту м''яча вдома, на тренуваннях і в іграх, спортивний застосунок для гравців, тренерів і батьків.', 'Pocket Radar makes portable speed radars for baseball, softball and other sports: measure pitch speed and exit velocity at home, in practice and in games, with a sports app for players, coaches and parents.', 'Pocket Radar виробляє точні портативні радари для вимірювання швидкості, якими користуються професіонали, тренери, спортсмени та скаути. Найчастіше їх застосовують у бейсболі й софтболі, щоб відстежувати швидкість подачі та швидкість вильоту м''яча після удару — вдома, на тренуваннях і в іграх. Пристрої підходять і для інших видів спорту, де важлива швидкість. Спортивний застосунок допомагає фіксувати й аналізувати вимірювання. На сайті можна обрати продукт залежно від ролі — гравець, тренер чи батьки, — знайти схеми налаштування й тренувань, зареєструвати гарантію або стати реселером. У США діє безплатна доставка від певної суми.', 'Pocket Radar builds accurate portable speed radars used by pros, coaches, athletes and scouts. They are most often used in baseball and softball to track pitching speed and exit velocity — at home, in practice and in games. The devices also suit other sports where speed matters. The sports app helps record and analyze measurements. On the site you can choose a product by role — player, coach or parent — find setup and training diagrams, register a warranty or become a reseller. Free US shipping applies above a certain order value.', 'Портативні радари швидкості
Швидкість подачі й вильоту м''яча
Спортивний застосунок
Рішення для гравців, тренерів і батьків
