SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'proplayai.com' OR LOWER(`name`) = LOWER('ProPlayAI'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'ProPlayAI', NULL, 'https://proplayai.com', NULL, NULL, 'ProPlayAI — тренування подачі в бейсболі за допомогою «атлетичного інтелекту»: аналіз кожної подачі, виправлення техніки, відстеження прогресу й порівняння з галузевими середніми; версії для гравців і тренерів.', 'ProPlayAI trains baseball pitching with athletic intelligence: analysis of every pitch, technique correction, progress tracking and comparison with industry averages, with versions for players and coaches.', 'ProPlayAI допомагає тренуватися розумніше, виправляючи й удосконалюючи подачу в бейсболі. Завдяки захопливим функціям і метрикам на основі даних тренування стає не лише ефективним, а й цікавим, тож гравці займаються регулярно й прогресують щодня. Для окремих гравців сервіс оцінює кожну подачу (до 100 на місяць), допомагає її виправити, відстежує прогрес і порівнює результати з галузевими середніми. Тариф для тренерів дає необмежену кількість гравців і подач, віддалений коучинг, порівняння гравців і можливість ділитися результатами з командою, тренерами та скаутами. Є 7-денний безплатний період і API для інтеграції в інші продукти.', 'ProPlayAI helps you train smarter by correcting and perfecting your baseball pitching. Immersive features and data-driven metrics make practice not only efficient but fun, so players keep at it and improve every day. For individual players it assesses each pitch (up to 100 per month), helps correct it, tracks progress and compares results with industry averages. The coaches plan includes unlimited players and pitches, virtual coaching, player comparisons and sharing results with the team, coaches and scouts. There is a 7-day free trial and an API for integrating into other products.', 'Аналіз кожної подачі
Виправлення техніки
Відстеження прогресу
Порівняння з галузевими середніми
Віддалений коучинг гравців
API для інтеграцій', 'Analysis of every pitch
Technique correction
Progress tracking
Comparison with industry averages
Virtual player coaching
API for integrations', 'Пітчери-бейсболісти та їхні тренери.', 'Baseball pitchers and their coaches.', 'mobile,web', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
