SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'reeplayer.com' OR LOWER(`name`) = LOWER('Reeplayer'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Reeplayer', NULL, 'https://www.reeplayer.com', NULL, NULL, 'Reeplayer — AI-камера для футболу з миттєвою обробкою: автономний запис і безплатні трансляції через вбудовану SIM, перегляд одразу після гри, необмежені ігри, команди й користувачі за 99 USD на місяць.', 'Reeplayer is an AI soccer camera with instant processing: autonomous recording and free live streaming via a built-in SIM, playback right after the game, and unlimited games, teams and users for 99 USD a month.', 'Reeplayer — AI-камера, що автономно записує й транслює футбольні матчі. Вбудована SIM-карта з глобальним тарифом дозволяє вести трансляції безплатно, а миттєва обробка дає змогу переглядати запис одразу після гри. Камера записує в 4K, видає відео 1080p, автоматично стежить за грою, захищена від негоди, зберігає до 30 ігор і швидко завантажує записи в застосунок Reeplayer. У підписці немає складних рівнів: необмежені ігри, команди й користувачі для всіх. Тренери використовують трансляції, щоб травмовані гравці й родини були на зв''язку, а кліпи — для скаутингу. Камера коштує 1499 USD одноразово, штатив — 349 USD, кейс — 99 USD; підписка — 99 USD на місяць.', 'Reeplayer is an AI camera that autonomously records and streams soccer games. A built-in SIM with a global data plan enables free streaming, and instant processing lets you watch the recording right after the game. The camera records in 4K, outputs 1080p, auto-tracks play, is weather-resistant, stores up to 30 games and uploads quickly to the Reeplayer app. The subscription has no complex tiers: unlimited games, teams and users for everyone. Coaches use streams to keep injured players and families connected and clips to get kids scouted. The camera costs 1,499 USD once, the tripod 349 USD and the case 99 USD; the subscription is 99 USD per month.', 'Автономний AI-запис і відстеження
Безплатні трансляції через SIM
Перегляд одразу після гри
Необмежені ігри, команди й користувачі
4K-запис і захист від негоди
Кліпи для скаутингу', 'Autonomous AI recording and tracking
Free streaming via SIM
Playback right after the game
Unlimited games, teams and users
4K recording and weatherproofing
Clips for scouting', 'Футбольні клуби, тренери, гравці й родини.', 'Soccer clubs, coaches, players and families.', 'mobile,web', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
