SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'reflexion.co' OR LOWER(`name`) = LOWER('Reflexion'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Reflexion', NULL, 'https://reflexion.co', NULL, NULL, 'Reflexion — технології когнітивних тренувань: персоналізовані вправи для мозку покращують час реакції, координацію «око — рука» й передбачення; станції для команд, Reflexion GO у змішаній реальності й мобільний застосунок.', 'Reflexion offers cognitive training technology: personalized brain workouts improve reaction time, eye-hand coordination and anticipation; stations for teams, Reflexion GO in mixed reality and a mobile app.', 'Reflexion тренує мозок за допомогою персоналізованих вправ, що покращують час реакції, координацію «око — рука» та здатність передбачати, допомагаючи вигравати частіше, швидше відновлюватися й досягати нових спортивних результатів. Рішення застосовують у спорті, реабілітації, для занять удома та для підтримки когнітивного здоров''я з віком. Reflexion GO — персоналізоване тренування у змішаній реальності, а мобільний застосунок дозволяє займатися з телефона. Для команд і великих груп є окремі рішення, наприклад із ними працює баскетбольна команда «Денвер Наггетс». На сайті є бібліотека вправ і відео, наукове обґрунтування, блог, інструкції з налаштування та магазин.', 'Reflexion trains your brain with personalized workouts that sharpen reaction time, eye-hand coordination and anticipation, helping you win more, recover faster and reach new athletic milestones. It is used in athletics, rehab, at home and for longevity and cognitive health. Reflexion GO provides personalized training in mixed reality, and the mobile app lets you train from your phone. Teams and large groups have dedicated solutions; the Denver Nuggets basketball team, for example, works with them. The site has a drill and video library, the science, a blog, setup instructions and a shop.', 'Тренування часу реакції
Координація «око — рука»
Reflexion GO у змішаній реальності
Мобільний застосунок
Рішення для команд
Реабілітація й довголіття', 'Reaction time training
Eye-hand coordination
Reflexion GO in mixed reality
Mobile app
Team solutions
Rehab and longevity', 'Спортсмени, команди, фахівці з реабілітації та люди, що дбають про когнітивне здоров''я.', 'Athletes, teams, rehab specialists and people focused on cognitive health.', 'mobile,desktop', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
