INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Reflexion trains your brain with personalized workouts that sharpen reaction time, eye-hand coordination and anticipation, helping you win more, recover faster and reach new athletic milestones. It is used in athletics, rehab, at home and for longevity and cognitive health. Reflexion GO provides personalized training in mixed reality, and the mobile app lets you train from your phone. Teams and large groups have dedicated solutions; the Denver Nuggets basketball team, for example, works with them. The site has a drill and video library, the science, a blog, setup instructions and a shop.', 'manual' FROM DUAL WHERE @new = 1;
