SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'reponestrength.com' OR LOWER(`name`) = LOWER('RepOne'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'RepOne', NULL, 'https://www.reponestrength.com', NULL, NULL, 'RepOne — підключене тренувальне обладнання: системи тренувань на основі швидкості (VBT), флайвіл, цифрова вага й моторизований опір EStack, а також набір застосунків для тренерів, інструкторів і атлетів будь-якого рівня.', 'RepOne makes connected training equipment: velocity-based training (VBT) systems, flywheel, digital weight and EStack motorized resistance, plus a suite of apps for coaches, trainers and athletes of every level.', 'RepOne розробляє підключене обладнання для силових тренувань і програмне забезпечення до нього. Лінійка включає системи тренувань на основі швидкості (velocity-based training), зокрема RepOne Tether, які вимірюють швидкість руху штанги, флайвіл-тренажери, цифрову вагу та технологію EStack — моторизований опір для середовищ із високим навантаженням. Новий продукт Profile Pro Pulse на базі EStack готується до виходу. Усе обладнання працює з набором застосунків RepOne Connected для тренерів, персональних тренерів і атлетів будь-якого рівня, які допомагають керувати навантаженням і бачити прогрес. Є рішення для команд, освітні матеріали, блог, база знань і магазин.', 'RepOne builds connected strength training equipment and the software around it. The lineup includes velocity-based training systems, such as the RepOne Tether, which measure bar speed, flywheel trainers, digital weight and EStack, motorized resistance for high-demand environments. The new Profile Pro Pulse powered by EStack is coming soon. All equipment works with the RepOne Connected app suite for coaches, trainers and athletes of every level, helping manage load and see progress. There are team solutions, education, a blog, a knowledge base and a shop.', 'Системи VBT для вимірювання швидкості
