SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'rezzil.com' OR LOWER(`name`) = LOWER('Rezzil'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Rezzil', NULL, 'https://rezzil.com', NULL, NULL, 'Rezzil — когнітивний спортивний тренажер у віртуальній реальності: занурювальні VR-тренування з футболу та інших видів, вимірювання когнітивних навичок валідованими тестами й оцінка ризику травм для команд і бізнесу.', 'Rezzil is a VR cognitive sports trainer: immersive soccer and other sports training, cognitive skill measurement with validated tests and injury risk assessment for teams and businesses.', 'Rezzil поєднує занурювальні тренування у віртуальній реальності з сучасними спортивними технологіями. Платформою користуються відомі спортивні команди, щоб підвищити якість тренувань і оптимізувати продуктивність. Атлети розвивають когнітивні навички — сприйняття, ухвалення рішень, реакцію — а спортивні науковці отримують валідовані тести, що кількісно оцінюють продуктивність і ризик травм. Тренування цікаві й залучають спортсменів, тож вони охоче повертаються до занять. Рішення доступні для команд, бізнесу, який хоче залучати клієнтів, і окремих користувачів. На сайті є новини, вакансії й контакти.', 'Rezzil blends immersive virtual reality training with cutting-edge sports technology. High-profile sports teams use the platform to elevate training and optimize performance. Athletes develop cognitive skills — perception, decision-making, reaction — while sports scientists get validated tests that quantify performance and injury risk. Sessions are fun and engaging, so athletes keep coming back. Solutions are available for teams, businesses that want to engage customers and individual users. The site has news, careers and contacts.', 'VR-тренування з футболу
Розвиток когнітивних навичок
Валідовані тести
Оцінка ризику травм
Рішення для команд і бізнесу', 'VR soccer training
Cognitive skill development
Validated tests
Injury risk assessment
Solutions for teams and businesses', 'Професійні команди, спортивні науковці, тренувальні центри й гравці.', 'Pro teams, sports scientists, training centers and players.', 'desktop', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
