SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'rundna.com' OR LOWER(`name`) = LOWER('RunDNA'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'RunDNA', NULL, 'https://rundna.com', NULL, NULL, 'RunDNA — безперервна освіта з бігу й технологія аналізу ходи: сертифікаційні курси аналітика ходьби та бігу (рівні 1 і 2), курси для тренерів і оцінка травматичного профілю кожного бігуна для профілактики травм.', 'RunDNA provides running continuing education and gait analysis technology: walking and running gait analyst certifications (levels 1 and 2), coaching courses and injury profile assessment for every runner.', 'RunDNA поєднує професійне навчання та технології аналізу ходи, щоб оцінювати профіль ризику травм кожного бігуна, запобігати травмам і покращувати результати. Освітні програми включають курс «Сертифікований аналітик ходьби, рівень 1» про біомеханіку ходьби й стратегії її корекції, «Сертифікований аналітик бігу, рівень 1» для фахівців, які хочуть надавати бігунам сервіс найвищого рівня, і «Рівень 2», що показує, як лікувати й тренувати бігунів зі складними травмами через поглиблену корекцію ходи, пліометрику, силові вправи та відпочинок. Також є курси для тренерів, що працюють як з новачками, так і з досвідченими бігунами.', 'RunDNA combines professional education and gait analysis technology to assess each runner''s injury profile, prevent injuries and maximize results. Education includes the Level 1 Certified Walking Gait Analyst course on walking biomechanics and gait retraining strategies, the Level 1 Certified Running Gait Analyst for professionals who want to give runners top-level service, and Level 2, which shows how to treat and train runners with complex injuries through advanced gait retraining, plyometrics, strength and rest. There are also coaching courses for those guiding beginners and experienced runners.', 'Курси аналітика ходьби та бігу
Сертифікація рівнів 1 і 2
Корекція ходи й пліометрика
Курси для тренерів
Технологія аналізу ходи', 'Walking and running gait analyst courses
Level 1 and 2 certification
Gait retraining and plyometrics
Courses for coaches
Gait analysis technology', 'Фізіотерапевти, тренери з бігу й фахівці зі спортивної медицини.', 'Physiotherapists, running coaches and sports medicine professionals.', 'web', 'course', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
