SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'scienceandmotion.com' OR LOWER(`name`) = LOWER('SAM PuttLab'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'SAM PuttLab', NULL, 'https://www.scienceandmotion.com', NULL, NULL, 'Science&Motion Sports — системи аналізу паттингу SAM PuttLab і SAM PuttStudio, баланс-лабораторія SAM BalanceLab, академія й сертифікації: допомагають покращити гру на гріні, адже значна частка ударів — це патти.', 'Science&Motion Sports offers SAM PuttLab and SAM PuttStudio putting analysis systems, the SAM BalanceLab, an academy and certifications to help improve play on the green, since putts make up a big share of shots.', 'Science&Motion Sports зосереджується на паттингу — частині гри, де, за даними компанії, припадає до 43% ударів. Система SAM PuttLab точно вимірює рух ключки під час патта й показує, що впливає на результат, а SAM PuttStudio створює повноцінну студію для тренувань паттингу. SAM BalanceLab аналізує баланс і розподіл ваги гравця. Компанія також пропонує освітню академію, сертифікації для інструкторів і каталог локацій та тренерів, які працюють із системами SAM. На сайті представлені встановлення, історії успіху, амбасадори, відгуки, підписки та довідка для кожної системи, а також форма запиту комерційної пропозиції.', 'Science&Motion Sports focuses on putting — the part of the game that, according to the company, accounts for up to 43% of shots. SAM PuttLab precisely measures club movement during a putt and shows what affects the result, while SAM PuttStudio creates a complete putting training studio. SAM BalanceLab analyzes a golfer''s balance and weight distribution. The company also offers an education academy, instructor certifications and a directory of locations and instructors using SAM systems. The site showcases installations, success stories, ambassadors, testimonials, subscriptions and help for each system, plus a quote request form.', 'Аналіз паттингу SAM PuttLab
Тренувальна студія SAM PuttStudio
Аналіз балансу SAM BalanceLab
Академія й сертифікації
Каталог тренерів', 'SAM PuttLab putting analysis
SAM PuttStudio training studio
SAM BalanceLab balance analysis
Academy and certifications
Instructor directory', 'Гольф-тренери, академії й гравці, що працюють над короткою грою.', 'Golf coaches, academies and players working on the short game.', 'desktop', 'basic', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
