INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Science&Motion Sports focuses on putting — the part of the game that, according to the company, accounts for up to 43% of shots. SAM PuttLab precisely measures club movement during a putt and shows what affects the result, while SAM PuttStudio creates a complete putting training studio. SAM BalanceLab analyzes a golfer''s balance and weight distribution. The company also offers an education academy, instructor certifications and a directory of locations and instructors using SAM systems. The site showcases installations, success stories, ambassadors, testimonials, subscriptions and help for each system, plus a quote request form.', 'manual' FROM DUAL WHERE @new = 1;
