-- Senaptec — Аналіз техніки та біомеханіка
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'senaptec.com' OR LOWER(`name`) = LOWER('Senaptec'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Senaptec', NULL, 'https://senaptec.com', NULL, NULL, 'Senaptec — сенсорні тренування для спорту: стробоскопічні окуляри Senaptec Strobe (Classic, Pro, Elite) і сенсорні станції 32 та 55 дюймів, що вчать мозок ефективніше обробляти поле зору; для тренувань, реабілітації й профілактики.', 'Senaptec offers sensory training for sport: Senaptec Strobe eyewear (Classic, Pro, Elite) and 32- and 55-inch Sensory Stations that teach the brain to process the field of vision more efficiently, for training, rehab and prevention.', 'Senaptec розробляє продукти й послуги для сенсорної продуктивності — тренування мозку обробляти поле зору та візуальні подразники ефективніше. Стробоскопічні окуляри Senaptec Strobe у версіях Classic, Pro та Elite періодично обмежують огляд, змушуючи мозок швидше обробляти інформацію. Сенсорні й тренувальні станції з екранами 32 та 55 дюймів оцінюють і тренують зорові та когнітивні навички. Рішення застосовують для спортивних тренувань, реабілітації та профілактики: у бейсболі, баскетболі, американському футболі, ракеткових видах, футболі (зокрема для воротарів), гольфі, а також у військових. Можна знайти станцію, замовити демо або комерційну пропозицію.', 'Senaptec develops sensory performance products and services that train the brain to process the field of vision and visual stimuli more efficiently. Senaptec Strobe eyewear in Classic, Pro and Elite versions intermittently limits vision, forcing the brain to process information faster. Sensory and Training Stations with 32- and 55-inch screens assess and train visual and cognitive skills. The solutions are used for athletic training, rehabilitation and preventive health in baseball, basketball, football, racket sports, soccer (including goalkeepers), golf and the military. You can find a station, book a demo or request a quote.', 'Стробоскопічні окуляри Strobe
Сенсорні станції 32 і 55 дюймів
Тренування зорової обробки
Програми для різних видів спорту
Реабілітація й профілактика', 'Strobe eyewear
32- and 55-inch Sensory Stations
Visual processing training
Programs for many sports
Rehab and prevention', 'Спортсмени, команди, тренувальні центри й фахівці з реабілітації.', 'Athletes, teams, training centers and rehabilitation specialists.', 'desktop', 'basic', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
