-- Sense Arena — Аналіз техніки та біомеханіка
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'sensearena.com' OR LOWER(`name`) = LOWER('Sense Arena'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Sense Arena', NULL, 'https://www.sensearena.com', NULL, NULL, 'Sense Arena — VR-тренування для хокею й тенісу: віртуальні вправи вдома, що розвивають швидкість ухвалення рішень, реакцію та когнітивні навички, щоб спортсмен думав швидше, реагував швидше й грав розумніше.', 'Sense Arena offers VR training for hockey and tennis: at-home virtual drills that sharpen decision-making, reaction time and cognitive skills so athletes think faster, react quicker and play smarter.', 'Sense Arena пропонує нове покоління спортивних тренувань у віртуальній реальності. Компанія наголошує, що створює не VR-ігри, а тренувальні інструменти: віртуальні вправи спеціально розроблені, щоб покращити ухвалення рішень, скоротити час реакції та розвинути когнітивні здібності, які відрізняють сильних спортсменів. Основні напрями — хокей і теніс. Займатися можна вдома в будь-який час, використовуючи VR-гарнітуру, і поступово розвивати ментальні навички, що переносяться на реальну гру. Тренування доповнюють звичайну підготовку на льоду чи корті й допомагають думати швидше, реагувати швидше й грати розумніше.', 'Sense Arena offers the next generation of sports training in virtual reality. The company stresses that it builds training tools rather than VR games: virtual drills are designed specifically to sharpen decision-making, enhance reaction times and master the cognitive abilities that define strong athletes. The main sports are hockey and tennis. You can train at home anytime with a VR headset and gradually build mental skills that transfer to the real game. Sessions complement regular on-ice or on-court practice and help athletes think faster, react quicker and play smarter.', 'VR-тренування для хокею
VR-тренування для тенісу
Розвиток ухвалення рішень
Скорочення часу реакції
Заняття вдома', 'VR hockey training
VR tennis training
Decision-making development
Faster reaction times
Training at home', 'Хокеїсти й тенісисти, а також їхні тренери.', 'Hockey and tennis players and their coaches.', 'desktop', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
