-- Shot Scope — Аналіз техніки та біомеханіка
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'shotscope.com' OR LOWER(`name`) = LOWER('Shot Scope'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Shot Scope', NULL, 'https://shotscope.com', NULL, NULL, 'Shot Scope — гольф-годинники з GPS, лазерні далекоміри, портативні GPS-пристрої, міні-лаунч-монітор LM1 і системи відстеження ударів, що допомагають знизити рахунок і гандикап завдяки статистиці гри. Є лімітовані версії.', 'Shot Scope makes GPS golf watches, laser rangefinders, GPS handhelds, the LM1 mini launch monitor and shot tracking systems that help lower your score and handicap through game statistics.', 'Shot Scope пропонує гольф-обладнання з аналітикою продуктивності. Лінійка включає GPS-годинники (V5, X5 з відстеженням ударів, G6), портативні GPS-пристрої H50 і H4, лазерні далекоміри серії PRO (L5, X, ZR, L2, LX), систему CONNEX, міні-портативний лаунч-монітор LM1 і системи автоматичного відстеження ударів. Зібрані дані відображаються в особистому кабінеті, де видно статистику гри й зони для покращення — це допомагає знижувати рахунок і гандикап. На сайті є магазин з аксесуарами, електронні ваучери, розпродажі, лімітовані випуски й підтримка. Обладнання підходить і новачкам, і досвідченим гравцям, які хочуть грати системніше.', 'Shot Scope offers golf equipment with performance analytics. The lineup includes GPS watches (V5, X5 with shot tracking, G6), H50 and H4 GPS handhelds, PRO series laser rangefinders (L5, X, ZR, L2, LX), the CONNEX system, the LM1 mini portable launch monitor and automatic shot tracking systems. Collected data appear in a personal dashboard showing game stats and areas to improve, helping lower your score and handicap. The site has a shop with accessories, e-vouchers, sales, limited editions and support. The gear suits beginners and experienced golfers who want a more systematic game.', 'GPS-годинники з відстеженням ударів
Лазерні далекоміри PRO
Портативні GPS-пристрої
Міні-лаунч-монітор LM1
Статистика в особистому кабінеті', 'GPS watches with shot tracking
PRO laser rangefinders
GPS handhelds
LM1 mini launch monitor
Stats in a personal dashboard', 'Гольфісти-аматори, які хочуть знизити рахунок за допомогою даних.', 'Amateur golfers who want to lower their score with data.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
