-- SKYTRAK — Аналіз техніки та біомеханіка
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'skytrakgolf.com' OR LOWER(`name`) = LOWER('SKYTRAK'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'SKYTRAK', NULL, 'https://www.skytrakgolf.com', NULL, NULL, 'SKYTRAK — домашні гольф-симулятори й лаунч-монітори (зокрема ST MAX) з точними даними удару, грою на реальних полях і тренувальними інструментами; членство з драйвінг-рейнджем, Sim Club, PinSeeker і оцінкою гри.', 'SKYTRAK makes home golf simulators and launch monitors (including the ST MAX) with accurate shot data, real course play and practice tools; membership with driving range, Sim Club, PinSeeker and game evaluation.', 'SKYTRAK пропонує лаунч-монітори та домашні гольф-симулятори, що поєднують точні дані про удар, гру на реальних полях і тренувальні інструменти. Флагманський монітор ST MAX можна придбати новим або за програмою обміну. На сайті можна підібрати симулятор, спланувати простір і проконсультуватися з фахівцем. Членство SKYTRAK відкриває програмне забезпечення: тариф Essential за 99,99 USD на рік включає драйвінг-рейндж SKYTRAK, членство в Sim Club, доступ до PinSeeker, бібліотеку тренувальних рейнджів і оцінку гри, а розширені плани додають гру на полях із бібліотеки. Є застосунок, гайд із налаштування, блог і підтримка.', 'SKYTRAK offers launch monitors and home golf simulators that combine accurate shot data, real course play and practice tools. The flagship ST MAX monitor can be bought new or via a trade-in. The site helps you choose a simulator, plan your space and talk to a sim pro. SKYTRAK membership unlocks software: the Essential plan at 99.99 USD per year includes the SKYTRAK driving range, Sim Club membership, PinSeeker access, a practice range library and game evaluation, while higher plans add course play from the library. There is an app, a setup guide, a blog and support.', 'Лаунч-монітор ST MAX
Домашні гольф-симулятори
Гра на реальних полях
Тренувальні рейнджі й PinSeeker
Оцінка гри
Програма обміну', 'ST MAX launch monitor
Home golf simulators
Real course play
Practice ranges and PinSeeker
Game evaluation
Trade-in program', 'Гольфісти, які хочуть тренуватися й грати вдома.', 'Golfers who want to practice and play at home.', 'mobile,desktop', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
