SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'smart2move.com' OR LOWER(`name`) = LOWER('Smart2Move'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Smart2Move', NULL, 'https://www.smart2move.com', NULL, NULL, 'Smart2Move — бездротові портативні подвійні 3D-силові платформи для гольфу, що вимірюють сили реакції опори, і ПЗ для їх аналізу й тренувань; швейцарська розробка, освітні курси для тренерів. Для тренерів і гравців.', 'Smart2Move makes wireless, portable dual 3D force plates for golf that measure ground reaction forces, plus software for analysis and training; Swiss engineering and education courses for coaches.', 'Smart2Move спеціалізується на бездротових портативних подвійних силових платформах і задає стандарт того, як у гольфі вимірюють, інтерпретують і застосовують сили реакції опори. Платформи 3D Dual Force Plates фіксують, як гравець взаємодіє із землею під час свінгу, а програмне забезпечення допомагає аналізувати ці дані, будувати тренування й покращувати гру. Компанія розробляє рішення у Швейцарії, поєднуючи апаратну й програмну частину. Для тренерів передбачено освітні програми, які пояснюють, як використовувати дані про сили в навчанні гравців. На сайті є опис продуктів, програмного забезпечення, компанії та підтримка.', 'Smart2Move specializes in wireless, portable dual force plates and sets the standard for how ground reaction forces are measured, interpreted and applied in golf. The 3D Dual Force Plates capture how a golfer interacts with the ground during the swing, and the software helps analyze the data, design training and improve the game. The company engineers its solutions in Switzerland, combining hardware and software. Education programs show coaches how to use force data when teaching players. The site describes the products, software, company and support.', 'Подвійні 3D-силові платформи
Сили реакції опори в свінгу
Програмне забезпечення для аналізу
Бездротові й портативні
Навчання для тренерів', 'Dual 3D force plates
Ground reaction forces in the swing
Analysis software
Wireless and portable
Coach education', 'Гольф-тренери, гравці високого рівня й центри підготовки.', 'Golf coaches, high-level players and training centers.', 'desktop,mobile', 'basic', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
