-- SOLOSHOT — Аналіз техніки та біомеханіка
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'soloshot.com' OR LOWER(`name`) = LOWER('SOLOSHOT'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'SOLOSHOT', NULL, 'https://soloshot.com', NULL, NULL, 'SOLOSHOT — персональний робот-оператор: автоматично стежить, знімає 4K-відео й монтує його, коли ви носите або кріпите Tag; новий SOLOSHOT3+ із сенсорами без розігріву й калібруванням за 15 секунд. Є аксесуари.', 'SOLOSHOT is a personal robot cameraman: it automatically tracks, records 4K video and edits it while you wear or mount the Tag; the new SOLOSHOT3+ has sensors with no warm-up and 15-second calibration.', 'SOLOSHOT — це робот-оператор, який знімає вас, поки ви займаєтеся спортом. Достатньо надягнути чи закріпити трекер Tag, і камера автоматично стежитиме, записуватиме 4K-відео й монтуватиме його. Нова версія SOLOSHOT3+ отримала набір сенсорів, що повністю усуває час розігріву й скорочує калібрування з трьох хвилин до 15 секунд, а відстеження стало надійнішим і точнішим. Пристрій підходить для серфінгу, кайтингу, тренувань на полі, змагань і будь-яких активностей, де немає кому тримати камеру. Також доступні SOLOSHOT3, аксесуари, застосунки й реферальна програма. Пристрій працює автономно, тож спортсмен може повністю зосередитися на тренуванні чи заїзді.', 'SOLOSHOT is a robot cameraman that films you while you play sports. Just wear or mount the Tag tracker, and the camera automatically follows you, records 4K video and edits it. The new SOLOSHOT3+ adds a suite of sensors that eliminates warm-up time and cuts calibration from three minutes to 15 seconds, with more robust and accurate tracking. It suits surfing, kiting, field training, competitions and any activity where nobody is around to hold the camera. SOLOSHOT3, accessories, apps and a referral program are also available. The device works autonomously, so the athlete can focus fully on the session.', 'Автоматичне відстеження за трекером Tag
Запис 4K-відео
Автоматичний монтаж
Калібрування за 15 секунд
Застосунки й аксесуари', 'Automatic tracking via the Tag
4K video recording
Automatic editing
15-second calibration
Apps and accessories', 'Серфери, кайтери, спортсмени й тренери, які знімають себе без оператора.', 'Surfers, kiters, athletes and coaches who film themselves without an operator.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
