-- SportAI — Аналіз техніки та біомеханіка
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'sportai.com' OR LOWER(`name`) = LOWER('SportAI'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'SportAI', NULL, 'https://sportai.com', NULL, NULL, 'SportAI — AI-платформа для ракеткових видів спорту, відзначена TIME Best Inventions 2025: аналіз техніки елітного рівня для гравців у теніс, падел і пікбол просто з телефона, рішення для тренерів, клубів, академій і бізнесу.', 'SportAI is an AI platform for racket sports, named a TIME Best Invention 2025: elite-level technique analysis for tennis, padel and pickleball players straight from a phone, with solutions for coaches, clubs, academies and enterprises.', 'SportAI робить аналіз техніки, який раніше був доступний лише топ-гравцям, доступним для всіх. Платформа на основі штучного інтелекту дає миттєвий аналіз продуктивності в тенісі, паделі та пікболі: достатньо зняти гру на телефон, і система розбере удари та рухи, підкаже, що покращити. Технологія отримала відзнаку TIME Best Inventions 2025 і використовується на професійних турнірах. Для гравців і тренерів є персональний аналіз, для клубів і академій — інструменти для роботи з учнями, а для компаній — корпоративні рішення та інтеграції. На сайті є новини, інформація про компанію та контакти. Аналіз працює без додаткових сенсорів.', 'SportAI brings technique analysis that used to be available only to top players to everyone. The AI platform gives immediate performance analysis in tennis, padel and pickleball: just film your play on a phone and the system breaks down your strokes and movement and suggests what to improve. The technology was named a TIME Best Invention 2025 and is used at professional tournaments. Players and coaches get personal analysis, clubs and academies get tools for working with students, and companies get enterprise solutions and integrations. The site has news, company information and contacts. Analysis works without extra sensors.', 'AI-аналіз техніки з телефона
Теніс, падел і пікбол
Миттєвий аналіз продуктивності
Рішення для тренерів і клубів
Корпоративні інтеграції', 'AI technique analysis from a phone
Tennis, padel and pickleball
Instant performance analysis
Solutions for coaches and clubs
Enterprise integrations', 'Гравці в теніс, падел і пікбол, тренери, клуби та академії.', 'Tennis, padel and pickleball players, coaches, clubs and academies.', 'mobile,web', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
