SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'squaregolf.com' OR LOWER(`name`) = LOWER('Square Golf'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Square Golf', NULL, 'https://squaregolf.com', NULL, NULL, 'Square Golf — лаунч-монітори й програмне забезпечення для гольф-симуляції, що поєднують сенсори й інтелектуальну обробку даних: реалістична гра й змістовний зворотний зв''язок, який переноситься на справжнє поле.', 'Square Golf makes launch monitors and golf simulation software that combine sensors with intelligent data processing for realistic play and meaningful feedback that translates to the course.', 'Square Golf створює занурювальну гольф-симуляцію на основі реальних даних про удар. Лаунч-монітори поєднують сучасні сенсори з інтелектуальною обробкою, щоб точно фіксувати параметри удару, а програмне забезпечення перетворює їх на реалістичну гру та змістовний зворотний зв''язок, що переноситься на справжнє поле. Принцип компанії — «зануритися в гру, залишаючись у реальності»: симуляція має бути не просто розвагою, а інструментом для покращення гри. На сайті представлені лаунч-монітори, програмне забезпечення, магазин, підтримка й відповіді на запитання; сайт доступний англійською та корейською мовами.', 'Square Golf creates immersive golf simulation powered by real shot data. Its launch monitors combine advanced sensing with intelligent processing to capture shot parameters accurately, and the software turns them into realistic play and meaningful feedback that translates to the real course. The company''s principle is to step into the game while staying in reality: simulation should be not just entertainment but a tool for improving your game. The site presents launch monitors, software, a shop, support and FAQs, in English and Korean.', 'Лаунч-монітори з сенсорами
Інтелектуальна обробка даних удару
Реалістична гольф-симуляція
Зворотний зв''язок для гри на полі
Програмне забезпечення', 'Sensor launch monitors
Intelligent shot data processing
Realistic golf simulation
Feedback for the course
Software', 'Гольфісти, які тренуються вдома чи в гольф-студіях.', 'Golfers practicing at home or in golf studios.', 'desktop,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
