SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'swimtraxx.com' OR LOWER(`name`) = LOWER('Swimtraxx'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Swimtraxx', NULL, 'https://swimtraxx.com', NULL, NULL, 'Swimtraxx — носимі трекери для плавання, що в реальному часі вимірюють пульс, показники гребка й час кіл: Swimtraxx One з 9 басейновими метриками, секундомір Chrono, безплатний застосунок і жодної підписки.', 'Swimtraxx makes wearable swim trackers that measure heart rate, stroke metrics and lap times in real time: Swimtraxx One with 9 pool metrics, the Chrono stopwatch, a free app and no subscription ever.', 'Swimtraxx створює носимі пристрої для змагальних плавців і тренерів. Swimtraxx One — спеціалізований пристрій для плавання, що вимірює дев''ять басейнових метрик, пульс та інші показники, допомагаючи відстежувати кожен гребок і тренуватися розумніше. Розробку вели разом з олімпійськими плавцями, а пристрій схвалено World Aquatics. Swimtraxx Chrono — професійний секундомір із потрійним дисплеєм, пам''яттю на 100 кіл і режимом пейсера. Почати можна з безплатного застосунку, а підписки немає взагалі. Є окремі розділи для спортсменів і тренерів, наукове обґрунтування та статті. Swimtraxx One коштує 249,99 EUR.', 'Swimtraxx builds wearables for competitive swimmers and coaches. Swimtraxx One is a swim-specific device measuring nine pool metrics, heart rate and more, helping you track every stroke and train smarter. It was co-developed with Olympic swimmers and is World Aquatics approved. Swimtraxx Chrono is a professional triple-display stopwatch with 100-lap memory and a pacer mode. You can start with the free app, and there is no subscription ever. There are sections for athletes and coaches, the science behind it and insights. Swimtraxx One costs 249.99 EUR.', '9 басейнових метрик і пульс
Показники гребка й час кіл у реальному часі
Схвалено World Aquatics
Секундомір Swimtraxx Chrono
