SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'swingbot.com' OR LOWER(`name`) = LOWER('Swingbot'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Swingbot', NULL, 'https://swingbot.com', NULL, NULL, 'Swingbot — автоматичний AI-аналіз свінгу в гольфі: необмежені аналізи будь-де за кілька хвилин, текстові результати, відео з анотаціями та відсоток точності, зйомка спереду або вздовж лінії та бібліотека відео.', 'Swingbot offers automated AI golf swing analysis: unlimited analyses anywhere in minutes, text results, annotated videos and an accuracy percentage, face-on or down-the-line angles and a video library.', 'Swingbot — ваш новий гольф-інструктор на основі штучного інтелекту, який бачить те, чого не помічає людське око. Ви записуєте свінг на телефон і за кілька хвилин отримуєте автоматичний аналіз — необмежено, будь-де й будь-коли. Результати доступні в застосунку або на сайті: текстовий розбір, персоналізоване відео з анотаціями та відсоток точності аналізу. Можна обрати один із двох ракурсів зйомки — спереду (face on) або вздовж лінії удару (down the line). Бібліотека відео в застосунку дозволяє швидко переглядати записи й результати. Доступ надається за членством, а на сайті є приклади аналізу та підтримка.', 'Swingbot is your new AI golf instructor that sees what the human eye misses. You record your swing on a phone and get an automated analysis within minutes — unlimited, anytime, anywhere. Results are available in the app or on the website: a text breakdown, a custom annotated video and an analysis accuracy percentage. You can choose face-on or down-the-line camera angles. The in-app video library lets you review recordings and results quickly. Access is by membership, and the site has sample analyses and support.', 'Автоматичний AI-аналіз свінгу
Необмежені аналізи
Відео з анотаціями
Відсоток точності аналізу
Два ракурси зйомки
Бібліотека відео', 'Automated AI swing analysis
Unlimited analyses
Annotated videos
Analysis accuracy percentage
Two camera angles
Video library', 'Гольфісти-аматори, які хочуть регулярний розбір свінгу.', 'Amateur golfers who want regular swing feedback.', 'mobile,web', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
