SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'tennibot.com' OR LOWER(`name`) = LOWER('Tennibot'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Tennibot', NULL, 'https://www.tennibot.com', NULL, NULL, 'Tennibot — AI-машина для подачі м''ячів для тенісу, пікболу й падела, зроблена в США: 4K-камери, 3D-відстеження, вправи, які складає AI, справжнє обертання й розміщення; стаціонарна Partner Lite від 1525 USD.', 'Tennibot is a US-made AI ball machine for tennis, pickleball and padel: 4K cameras, 3D tracking, AI-built drills and real spin and placement; the stationary Partner Lite starts at 1,525 USD.', 'Tennibot створює AI-машини для подачі м''ячів для тенісу, пікболу й падела. Пристрої оснащено 4K-камерами та 3D-відстеженням, тож машина бачить гравця й формує вправи під нього, подаючи м''ячі зі справжнім обертанням і точним розміщенням. Усі моделі Tennibot працюють з однаковими AI-вправами. Нова стаціонарна Partner Lite важить 25 фунтів і коштує від 1525 USD за вид спорту; теніс і падел працюють на одному пристрої, а пікбол — окремий. На сайті пояснено, як працює система, для кого вона підходить — гравців, тренерів, клубів, — і наведено лінійку моделей. Діє трирічна гарантія та безплатна доставка.', 'Tennibot builds AI ball machines for tennis, pickleball and padel. The devices have 4K cameras and 3D tracking, so the machine sees the player and builds drills around them, feeding balls with real spin and precise placement. Every Tennibot runs the same AI drills. The new stationary Partner Lite weighs 25 lbs and starts at 1,525 USD per sport; tennis and padel share one unit, while pickleball is a separate unit. The site explains how it works, who it is for — players, coaches and clubs — and shows the model range. It comes with a three-year warranty and free shipping.', 'AI-вправи під гравця
4K-камери й 3D-відстеження
Теніс, пікбол і падел
Справжнє обертання й розміщення
Трирічна гарантія', 'AI drills built for the player
4K cameras and 3D tracking
Tennis, pickleball and padel
Real spin and placement
Three-year warranty', 'Тенісисти, гравці в пікбол і падел, тренери й клуби.', 'Tennis, pickleball and padel players, coaches and clubs.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
