SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'tritonwear.com' OR LOWER(`name`) = LOWER('TritonWear'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'TritonWear', NULL, 'https://www.tritonwear.com', NULL, NULL, 'TritonWear — AI-платформа коучингу для змагальних плавців: відстежує кожен метр і діагностує кожен гребок, щотижня каже, що виправити, із планом для команди й кожного плавця; живі дані, звіти й безплатний планувальник сезону.', 'TritonWear is an AI coaching platform for competitive swimmers: it tracks every metre and diagnoses every stroke, then says what to fix each week with a plan for the team and each swimmer; live data, reports and a free season planner.', 'TritonWear — платформа для команд з плавання, що поєднує сенсори й AI. Система відстежує кожен проплитий метр і діагностує кожен гребок, а потім щотижня підказує, що саме виправити, формуючи план для команди та кожного плавця. Під час тренування тренер бачить потокові метрики — темп, пульс, частоту гребків, дистанцію, — з яких будується повний профіль спортсмена. Дашборд, живі тренування, звіти й аналіз допомагають досягати цілей. Членство оплачується за спортсмена без прихованих платежів і вартості обладнання; часто команди перекладають вартість на спортсмена чи батьків. Річний план — 287 USD на спортсмена, з квартальними зустрічами з командою науковців даних. Безплатно доступний планувальник сезону.', 'TritonWear is a platform for swim teams that combines sensors and AI. It tracks every metre swum and diagnoses every stroke, then tells you each week exactly what to fix, with a tailored plan for the team and every swimmer. During training the coach sees streaming metrics — pace, heart rate, stroke rate and distance — that build a complete athlete profile. The dashboard, live training, reports and analysis help reach goals. Membership is priced per athlete with no hidden fees or equipment costs; teams often pass the cost to athletes or parents. The annual plan is 287 USD per athlete and includes quarterly meetings with the data science team. A season planner is free.', 'Відстеження кожного метра й гребка
Щотижневі AI-рекомендації
Живі метрики темпу, пульсу й гребків
Звіти й аналіз
Зустрічі з науковцями даних
Безплатний планувальник сезону', 'Every metre and stroke tracked
Weekly AI recommendations
Live pace, heart rate and stroke metrics
Reports and analysis
Data science team meetings
Free season planner', 'Тренери й команди змагального плавання.', 'Competitive swim coaches and teams.', 'web,mobile', 'basic', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
