SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'uneekor.com' OR LOWER(`name`) = LOWER('Uneekor'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Uneekor', NULL, 'https://uneekor.com', NULL, NULL, 'Uneekor — стельові та наземні лаунч-монітори для гольфу (EYE XO2, EYE XO, EYE XR, EYE MINI) з точними даними м''яча й ключки, готові симулятори SIMKIT, камери Swing Optix, віртуальні поля й рішення для бізнесу.', 'Uneekor makes overhead and ground golf launch monitors (EYE XO2, EYE XO, EYE XR, EYE MINI) with precise ball and club data, SIMKIT simulators, Swing Optix cameras, virtual courses and business solutions.', 'Uneekor виробляє лаунч-монітори, симулятори й програмне забезпечення для гольфу, що дають точні дані про м''яч і ключку та захопливу гру вдома й у комерційних боксах. Стельові монітори EYE XO2, EYE XO і EYE XR встановлюються над зоною удару, а наземні EYE MINI, MINI LITE і MINI CORE стоять поруч із гравцем. Готові набори SIMKIT поєднують монітор із проєктором, комп''ютером, огородженням і покриттям, а можна зібрати власний симулятор. Камери Swing Optix записують свінг. Є програмне забезпечення та членства, віртуальні гольф-поля, рішення для гольф-клубів, лаунжів, тренерських центрів, готелів, ресторанів і навчальних закладів.', 'Uneekor builds golf launch monitors, simulators and software that deliver precise ball and club data with immersive play at home and in commercial bays. The EYE XO2, EYE XO and EYE XR overhead monitors mount above the hitting area, while the EYE MINI, MINI LITE and MINI CORE ground units sit beside the golfer. SIMKIT packages combine a monitor with a projector, computer, enclosure and turf, or you can build your own simulator. Swing Optix cameras record the swing. There is software and memberships, virtual golf courses and solutions for golf facilities, lounges, coaching centers, hotels, restaurants and schools.', 'Стельові монітори EYE XO2, XO, XR
Наземні EYE MINI
Готові симулятори SIMKIT
Камери Swing Optix
Віртуальні поля
Рішення для бізнесу', 'EYE XO2, XO, XR overhead monitors
EYE MINI ground units
SIMKIT simulators
Swing Optix cameras
Virtual courses
Business solutions', 'Гольфісти, власники домашніх симуляторів і комерційні гольф-заклади.', 'Golfers, home simulator owners and commercial golf venues.', 'desktop', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
