INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Uneekor builds golf launch monitors, simulators and software that deliver precise ball and club data with immersive play at home and in commercial bays. The EYE XO2, EYE XO and EYE XR overhead monitors mount above the hitting area, while the EYE MINI, MINI LITE and MINI CORE ground units sit beside the golfer. SIMKIT packages combine a monitor with a projector, computer, enclosure and turf, or you can build your own simulator. Swing Optix cameras record the swing. There is software and memberships, virtual golf courses and solutions for golf facilities, lounges, coaching centers, hotels, restaurants and schools.', 'manual' FROM DUAL WHERE @new = 1;
