-- Vicon — Аналіз техніки та біомеханіка
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'vicon.com' OR LOWER(`name`) = LOWER('Vicon'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Vicon', NULL, 'https://www.vicon.com', NULL, NULL, 'Vicon — системи захоплення руху з маркерами й без маркерів (Nexus Markerless) для біомеханіки, спортивної науки, клінічного аналізу ходи й досліджень, а також для кіно, ігор, VR, робототехніки й інженерії.', 'Vicon makes marker-based and markerless (Nexus Markerless) motion capture systems for biomechanics, sports science, clinical gait analysis and research, as well as film, games, VR, robotics and engineering.', 'Vicon створює камери, програмне забезпечення та системи захоплення руху для різних галузей. У напрямі наук про життя системи аналізують рух для спорту, біомеханіки, клінічного аналізу ходи, спортивної науки та досліджень тварин. Нова Nexus Markerless дозволяє в одній системі захоплювати рух і з маркерами, і без них. Для розваг Vicon пропонує відстеження для кіно, серіалів, ігор, анімації, VTubing та інді-творців, а для інженерії — для автономного транспорту, робототехніки та ергономіки. Програмні продукти включають Shōgun для VFX. Для спортивних лабораторій і клінік рішення Vicon дають високоточні дані про рух спортсменів і пацієнтів.', 'Vicon builds motion capture cameras, software and systems for many industries. In life sciences its systems analyze movement for sports, biomechanics, clinical gait analysis, sports science and animal science. The new Nexus Markerless lets one system capture both with and without markers. For entertainment Vicon offers tracking for film, episodic TV, games, animation, VTubing and indie creators, and for engineering — for autonomous vehicles, robotics and human factors. Software includes Shōgun for VFX. For sports labs and clinics, Vicon solutions deliver high-precision movement data for athletes and patients.', 'Захоплення руху з маркерами й без
Nexus Markerless
Біомеханіка й спортивна наука
Клінічний аналіз ходи
Рішення для кіно та ігор
Інженерні застосування', 'Marker-based and markerless capture
Nexus Markerless
Biomechanics and sports science
Clinical gait analysis
Film and game solutions
Engineering applications', 'Спортивні лабораторії, біомеханіки, клініки, університети та студії.', 'Sports labs, biomechanists, clinics, universities and studios.', 'desktop', 'course', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
