-- Vitruve — Аналіз техніки та біомеханіка
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'vitruve.fit' OR LOWER(`name`) = LOWER('Vitruve'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Vitruve', NULL, 'https://vitruve.fit', NULL, NULL, 'Vitruve — технології для розвитку атлетів: таймінгові ворота Vitruve Speed для спринтів і реакції, пристрій Force з метриками силової платформи, конструктор програм Builder замість таблиць і Labs для об''єднання даних.', 'Vitruve offers athlete development technology: Vitruve Speed timing gates for sprints and reaction, the Force device with force-plate-validated metrics, the Builder programming tool instead of spreadsheets, and Labs to connect data.', 'Vitruve пропонує набір інструментів для тренерів і спортивних закладів. Vitruve Speed — нові таймінгові ворота для спринтів і тренування реакції. Vitruve Force — один пристрій, що дає всі ключові метрики й валідований порівняно з силовою платформою та 3D-системою VICON. Vitruve Builder замінює статичні таблиці динамічним програмуванням тренувань, а Vitruve Labs об''єднує всі дані для повного контексту. Рішення адаптовані для коледжів, старших шкіл із великими групами, приватних центрів, які перетворюють елітні технології на бізнес, професійних команд і онлайн-коучингу з віддаленим програмуванням. Є академія, блог і підтримка.', 'Vitruve offers a set of tools for coaches and sports facilities. Vitruve Speed is a new timing gate system for sprints and reaction training. Vitruve Force is one device that gives every key metric and is validated against a force plate and VICON 3D. Vitruve Builder replaces static spreadsheets with dynamic programming, and Vitruve Labs connects all your data for total context. Solutions are tailored for colleges, high schools with large groups, private facilities turning elite technology into business growth, professional teams and online coaching with remote programming. There is an academy, a blog and support.', 'Таймінгові ворота Vitruve Speed
Пристрій Force з валідацією
Конструктор програм Builder
Об''єднання даних у Labs
Рішення для шкіл, коледжів і профі', 'Vitruve Speed timing gates
Validated Force device
Builder programming tool
Data connection in Labs
Solutions for schools, colleges and pros', 'Тренери з фізпідготовки, коледжі, школи, приватні центри й професійні команди.', 'Strength and conditioning coaches, colleges, schools, private facilities and pro teams.', 'mobile,web', 'basic', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
