SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'vizualedge.com' OR LOWER(`name`) = LOWER('Vizual Edge'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Vizual Edge', NULL, 'https://www.vizualedge.com', NULL, NULL, 'Vizual Edge — онлайн-система тренування зору й мозку для спортсменів, команд і закладів: розвиває зорові та когнітивні навички для швидшої реакції й кращих рішень у бейсболі, хокеї, тенісі, гольфі, кіберспорті тощо.', 'Vizual Edge is an online eye-brain training system for athletes, teams and facilities: it develops visual and cognitive skills for faster reactions and better decisions in baseball, hockey, tennis, golf, esports and more.', 'Vizual Edge — онлайн-система тренування зв''язку «око — мозок», що розвиває зорові й когнітивні навички, які стоять за швидкою реакцією, кращими рішеннями та високими результатами. Система Edge доступна в браузері, тож займатися можна будь-де. Програми адаптовані для бейсболу, хокею, софтболу, пікболу, тенісу, лакросу, американського футболу, гольфу, баскетболу, футболу, кіберспорту, волейболу та тактичних професій. Рішення є для окремих атлетів, команд, спортивних закладів, загального добробуту та офтальмологічних практик. На сайті пояснюються зорові навички, є блог, ресурси, відповіді на запитання й підписка з регулярною оплатою.', 'Vizual Edge is an online eye-brain training system that develops the visual and cognitive skills behind faster reactions, better decisions and high performance. The Edge System runs in the browser, so you can train anywhere. Programs are adapted for baseball, hockey, softball, pickleball, tennis, lacrosse, football, golf, basketball, soccer, esports, volleyball and tactical professions. Solutions exist for individual athletes, teams, facilities, general wellness and eye care practices. The site explains visual skills and has a blog, resources, FAQs and a recurring subscription.', 'Онлайн-тренування зору й мозку
Розвиток реакції та ухвалення рішень
Програми для багатьох видів спорту
Рішення для команд і закладів
Підтримка офтальмологів', 'Online eye-brain training
Reaction and decision-making development
Programs for many sports
Solutions for teams and facilities
Support for eye care practices', 'Спортсмени, команди, спортивні заклади й офтальмологи.', 'Athletes, teams, sports facilities and eye care professionals.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
