SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'voicecaddie.com' OR LOWER(`name`) = LOWER('Voice Caddie'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Voice Caddie', NULL, 'https://voicecaddie.com', NULL, NULL, 'Voice Caddie — гольф-технології для поля й тренувань: лаунч-монітори й аналізатори свінгу Swing Caddie (SC4 PRO, SC300i, SC200 Plus), цифрова палиця SS10, лазерні далекоміри та GPS-годинники T11 Pro і T9.', 'Voice Caddie offers golf tech for the course and practice: Swing Caddie launch monitors and swing analyzers (SC4 PRO, SC300i, SC200 Plus), the SS10 digital swing stick, laser rangefinders and T11 Pro and T9 GPS watches.', 'Voice Caddie пропонує гольф-обладнання, що допомагає грати краще на полі й тренуватися продуктивніше. Лінійка лаунч-моніторів і аналізаторів свінгу Swing Caddie включає SC4 PRO, SC300i, SC200 Plus і цифрову тренувальну палицю SS10, що вимірюють дистанції та параметри удару під час тренувань. Лазерні далекоміри SL3, Laser FIT, компактний SL Mini і TL1 допомагають точно визначати відстань до цілі, а GPS-годинники T11 Pro, T11 LT і T9 показують дистанції на полі. Для кожної категорії є таблиці порівняння моделей, аксесуари, відновлені пристрої зі знижкою й комплекти. Пристрої підходять і для новачків, і для досвідчених гравців, які стежать за своїми дистанціями.', 'Voice Caddie offers golf gear that helps you play better on the course and practice more productively. The Swing Caddie launch monitor and swing analyzer lineup includes the SC4 PRO, SC300i, SC200 Plus and the SS10 digital swing stick, which measure distances and shot parameters during practice. The SL3, Laser FIT, compact SL Mini and TL1 laser rangefinders measure distance to the target precisely, and the T11 Pro, T11 LT and T9 GPS watches show distances on the course. Each category has comparison tables, accessories, discounted refurbished devices and bundles. The devices suit beginners and experienced golfers who track their distances.', 'Лаунч-монітори Swing Caddie
Цифрова палиця SS10
Лазерні далекоміри
GPS-годинники для гольфу
Порівняння моделей', 'Swing Caddie launch monitors
SS10 digital swing stick
Laser rangefinders
GPS golf watches
Model comparisons', 'Гольфісти-аматори, які тренуються на рейнджі й грають на полі.', 'Amateur golfers practicing at the range and playing on the course.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
