INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'short_description', 'en', 'Voice Caddie offers golf tech for the course and practice: Swing Caddie launch monitors and swing analyzers (SC4 PRO, SC300i, SC200 Plus), the SS10 digital swing stick, laser rangefinders and T11 Pro and T9 GPS watches.', 'manual' FROM DUAL WHERE @new = 1;
INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Voice Caddie offers golf gear that helps you play better on the course and practice more productively. The Swing Caddie launch monitor and swing analyzer lineup includes the SC4 PRO, SC300i, SC200 Plus and the SS10 digital swing stick, which measure distances and shot parameters during practice. The SL3, Laser FIT, compact SL Mini and TL1 laser rangefinders measure distance to the target precisely, and the T11 Pro, T11 LT and T9 GPS watches show distances on the course. Each category has comparison tables, accessories, discounted refurbished devices and bundles. The devices suit beginners and experienced golfers who track their distances.', 'manual' FROM DUAL WHERE @new = 1;
