-- WIN Reality — Аналіз техніки та біомеханіка
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'winreality.com' OR LOWER(`name`) = LOWER('WIN Reality'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'WIN Reality', NULL, 'https://winreality.com', NULL, NULL, 'WIN Reality — VR і AI для бейсболу й софтболу: застосунок Train VR для Meta Quest тренує розпізнавання подач і рішення про удар на ігровій швидкості, Swing AI аналізує свінг з телефона, Smart PARK дає дані з полів.', 'WIN Reality offers VR and AI for baseball and softball: the Train VR app for Meta Quest trains pitch recognition and swing decisions at game speed, Swing AI analyzes your swing from a phone, and Smart PARK delivers field data.', 'WIN Reality допомагає гравцям і тренерам у бейсболі та софтболі тренуватися розумніше. Застосунок Train VR для Meta Quest дає повторення на ігровій швидкості у віртуальній реальності, тренуючи розпізнавання подач і ухвалення рішень про удар. Для занять потрібні гарнітура Meta Quest і насадки WIN — кріплення для біти або коротка біта. Мобільний застосунок Swing AI миттєво аналізує свінг за відео з телефона й пропонує персональні вправи. Smart PARK передає дані гри в реальному часі на смарт-пристрої з підключених полів і закладів. Є рішення для тренерів, гравців, фанатів, закладів і організацій, а також пакетні підписки зі знижкою.', 'WIN Reality helps baseball and softball players and coaches train smarter. The Train VR app for Meta Quest provides game-speed reps in virtual reality, training pitch recognition and swing decisions. Sessions require a Meta Quest headset and WIN attachments — a bat attachment or a short bat. The Swing AI mobile app instantly analyzes your swing from phone video and suggests personalized drills. Smart PARK streams real-time game data to smart devices from connected fields and facilities. There are solutions for coaches, players, fans, facilities and organizations, plus discounted subscription bundles.', 'VR-тренування Train VR для Meta Quest
Розпізнавання подач і рішення про удар
Swing AI — аналіз свінгу з телефона
Насадки для біти
Smart PARK із даними з полів', 'Train VR for Meta Quest
Pitch recognition and swing decisions
Swing AI phone analysis
Bat attachments
Smart PARK field data', 'Бейсболісти й софтболісти, тренери, заклади та організації.', 'Baseball and softball players, coaches, facilities and organizations.', 'mobile,desktop', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
