-- XbotGo — Аналіз техніки та біомеханіка
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'xbotgo.com' OR LOWER(`name`) = LOWER('XbotGo'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'XbotGo', NULL, 'https://xbotgo.com', NULL, NULL, 'XbotGo — AI-камери для спорту: Falcon із 4K-відео й автоматичним відстеженням гри, Chameleon для смартфона, безплатні трансляції, монтаж хайлайтів і хмарне сховище для футболу, баскетболу, бейсболу, хокею та інших.', 'XbotGo makes AI sports cameras: Falcon with 4K video and automatic game tracking, Chameleon for smartphones, free live streaming, highlight editing and cloud storage for soccer, basketball, baseball, hockey and more.', 'XbotGo створює AI-камери, які роблять зйомку кожної гри простою. Модель Falcon записує 4K-відео й автоматично стежить за грою за допомогою AI, а Chameleon перетворює смартфон на камеру з автотрекінгом. До камер пропонуються безплатні трансляції наживо, редагування хайлайтів і хмарне сховище. Підтримуються футбол, баскетбол, бейсбол, хокей, лакрос, американський футбол і гандбол. Рішення розраховані на батьків, які хочуть знімати дітей, тренерів, що аналізують ігри, клуби й самих гравців. Серед аксесуарів — штативи NT1, NT4 і NT4 Pro, парасолька, чохол і пульт. Є застосунок, посібник користувача й центр допомоги.', 'XbotGo builds AI sports cameras that make every game easy to capture. Falcon records 4K video and automatically follows the action with AI, while Chameleon turns a smartphone into an auto-tracking camera. The cameras come with free live streaming, highlight editing and cloud storage. Supported sports include soccer, basketball, baseball, ice hockey, lacrosse, football and handball. Solutions target parents filming their kids, coaches analyzing games, clubs and players. Accessories include NT1, NT4 and NT4 Pro tripods, an umbrella, a case and a remote. There is an app, a user guide and a help center.', '4K-камера Falcon з AI-відстеженням
Chameleon для смартфона
Безплатні трансляції
Монтаж хайлайтів
Хмарне сховище
Штативи й аксесуари', '4K Falcon camera with AI tracking
Chameleon for smartphones
Free live streaming
Highlight editing
Cloud storage
Tripods and accessories', 'Батьки юних спортсменів, тренери, клуби й гравці.', 'Parents of young athletes, coaches, clubs and players.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
