-- Xsens — Аналіз техніки та біомеханіка
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'xsens.com' OR LOWER(`name`) = LOWER('Xsens'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Xsens', NULL, 'https://www.xsens.com', NULL, NULL, 'Xsens (Movella) — інерційні костюми захоплення руху та сенсорні модулі: для здоров''я й спорту (біомеханіка, профілактика травм, продуктивність), розваг, гуманоїдних роботів і промислової автоматизації.', 'Xsens (Movella) makes inertial motion capture suits and sensor modules: for health and sports (biomechanics, injury prevention, performance), entertainment, humanoid robotics and industrial automation.', 'Xsens постачає костюми захоплення руху та інерційні сенсорні модулі для кількох галузей. У напрямі здоров''я та спорту продукти використовують для біомеханічних досліджень, безпеки, профілактики травм і підвищення спортивної продуктивності, а спеціальне програмне забезпечення допомагає аналізувати рух поза лабораторією. Для розваг Xsens пропонує захоплення руху для анімації, ігор, кіно, VFX і стримінгу. Для гуманоїдних роботів — рішення для телеоперування, навчання AI/ML, розробки й симуляції. Інерційні сенсори для автоматизації та мобільності застосовують у роботах і транспорті, камерах, автономних мобільних роботах і 3D-картографуванні.', 'Xsens supplies motion capture suits and inertial sensor modules for several industries. In health and sports its products are used for biomechanical research, safety, injury prevention and sports performance, and dedicated software helps analyze movement outside the lab. For entertainment Xsens offers motion capture for animation, games, film, VFX and streaming. For humanoid robots there are solutions for teleoperation, AI/ML training, development and simulation. Inertial sensors for automation and mobility are used in robots and vehicles, cameras, indoor AMRs and 3D mapping.', 'Інерційні костюми захоплення руху
ПЗ для здоров''я й спорту
Біомеханіка й профілактика травм
Рішення для анімації та ігор
Сенсори для робототехніки', 'Inertial motion capture suits
Health and sports software
Biomechanics and injury prevention
Animation and game solutions
Sensors for robotics', 'Спортивні науковці, біомеханіки, клініки, аніматори та інженери.', 'Sports scientists, biomechanists, clinics, animators and engineers.', 'desktop', 'course', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
